{
  "name": "Radio Streamer Mobile",
  "description": "A high-quality mobile radio streaming application for listening to RNE stations with live visualizers and HLS support.",
  "requestFramePermissions": [
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface RadioStation {
  id: string;
  name: string;
  url: string;
  description: string;
  color: string;
  image: string;
}

export enum PlayerState {
  IDLE = 'IDLE',
  LOADING = 'LOADING',
  PLAYING = 'PLAYING',
  PAUSED = 'PAUSED',
  ERROR = 'ERROR'
}

import { RadioStation } from './types';

export const STATIONS: RadioStation[] = [
  {
    id: 'rne5-alicante',
    name: 'Radio 5 Alicante',
    url: 'https://rnelivestream.rtve.es/rne5/ali/master.m3u8?idasset=6116423',
    description: 'Información y noticias de Alicante',
    color: '#ef4444',
    image: 'https://picsum.photos/seed/radio5/400/400'
  },
  {
    id: 'rne1-valencia',
    name: 'Radio 1',
    url: 'https://rnelivestream.rtve.es/rne1/val/master.m3u8?hdnts=exp%3D1769542451~hmac%3D9e11f544483a50b3f60c238e92c36d07e09572e6117a558eb5e58ff475b3f3a7&idasset=3893537',
    description: 'Emisión nacional de Radio Nacional de España',
    color: '#3b82f6',
    image: 'https://picsum.photos/seed/radio1/400/400'
  }
];

import React, { useEffect, useRef } from 'react';
import * as d3 from 'd3';

interface VisualizerProps {
  analyser: AnalyserNode | null;
  color: string;
  isPaused: boolean;
}

const Visualizer: React.FC<VisualizerProps> = ({ analyser, color, isPaused }) => {
  const svgRef = useRef<SVGSVGElement>(null);

  useEffect(() => {
    if (!svgRef.current || !analyser) return;

    const svg = d3.select(svgRef.current);
    const width = svgRef.current.clientWidth;
    const height = svgRef.current.clientHeight;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    const barWidth = (width / bufferLength) * 2.5;
    let animationId: number;

    const draw = () => {
      animationId = requestAnimationFrame(draw);
      analyser.getByteFrequencyData(dataArray);

      const bars = svg.selectAll('rect')
        .data(Array.from(dataArray).slice(0, 40));

      bars.enter()
        .append('rect')
        .merge(bars as any)
        .attr('x', (d, i) => i * (barWidth + 2))
        .attr('y', d => height - (d / 255) * height)
        .attr('width', barWidth)
        .attr('height', d => (d / 255) * height)
        .attr('fill', color)
        .attr('opacity', isPaused ? 0.3 : 1)
        .attr('rx', 2);

      bars.exit().remove();
    };

    draw();

    return () => {
      cancelAnimationFrame(animationId);
    };
  }, [analyser, color, isPaused]);

  return (
    <div className="w-full h-24 flex items-center justify-center overflow-hidden">
      <svg ref={svgRef} className="w-full h-full" />
    </div>
  );
};

export default Visualizer;

import React, { useEffect, useRef, forwardRef, useImperativeHandle } from 'react';
import { PlayerState } from '../types';

declare const Hls: any;

interface AudioEngineProps {
  url: string;
  volume: number;
  isMuted: boolean;
  onStateChange: (state: PlayerState) => void;
  onAnalyserCreated: (analyser: AnalyserNode) => void;
}

export interface AudioEngineHandle {
  play: () => void;
  pause: () => void;
  toggle: () => void;
}

const AudioEngine = forwardRef<AudioEngineHandle, AudioEngineProps>(({
  url,
  volume,
  isMuted,
  onStateChange,
  onAnalyserCreated
}, ref) => {
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const hlsRef = useRef<any>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);

  useImperativeHandle(ref, () => ({
    play: () => audioRef.current?.play(),
    pause: () => audioRef.current?.pause(),
    toggle: () => {
      if (audioRef.current?.paused) {
        audioRef.current.play();
      } else {
        audioRef.current?.pause();
      }
    }
  }));

  const setupWebAudio = () => {
    if (!audioRef.current) return;
    if (!audioContextRef.current) {
      const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
      audioContextRef.current = new AudioContextClass();
      analyserRef.current = audioContextRef.current.createAnalyser();
      analyserRef.current.fftSize = 128;

      sourceRef.current = audioContextRef.current.createMediaElementSource(audioRef.current);
      sourceRef.current.connect(analyserRef.current);
      analyserRef.current.connect(audioContextRef.current.destination);

      onAnalyserCreated(analyserRef.current);
    }

    if (audioContextRef.current.state === 'suspended') {
      audioContextRef.current.resume();
    }
  };

  useEffect(() => {
    if (!audioRef.current) return;

    onStateChange(PlayerState.LOADING);

    if (Hls.isSupported()) {
      if (hlsRef.current) {
        hlsRef.current.destroy();
      }
      const hls = new Hls();
      hlsRef.current = hls;
      hls.loadSource(url);
      hls.attachMedia(audioRef.current);
      hls.on(Hls.Events.MANIFEST_PARSED, () => {
        // audioRef.current?.play().catch(() => onStateChange(PlayerState.PAUSED));
      });
      hls.on(Hls.Events.ERROR, (_: any, data: any) => {
        if (data.fatal) {
           onStateChange(PlayerState.ERROR);
        }
      });
    } else if (audioRef.current.canPlayType('application/vnd.apple.mpegurl')) {
      audioRef.current.src = url;
    }

    return () => {
      if (hlsRef.current) {
        hlsRef.current.destroy();
      }
    };
  }, [url]);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = volume;
      audioRef.current.muted = isMuted;
    }
  }, [volume, isMuted]);

  return (
    <audio
      ref={audioRef}
      onPlay={() => {
        setupWebAudio();
        onStateChange(PlayerState.PLAYING);
      }}
      onPause={() => onStateChange(PlayerState.PAUSED)}
      onWaiting={() => onStateChange(PlayerState.LOADING)}
      onPlaying={() => onStateChange(PlayerState.PLAYING)}
      onEnded={() => onStateChange(PlayerState.IDLE)}
      onError={() => onStateChange(PlayerState.ERROR)}
      crossOrigin="anonymous"
    />
  );
});

AudioEngine.displayName = 'AudioEngine';

export default AudioEngine;

import React, { useState, useRef, useCallback } from 'react';
import { PlayerState, RadioStation } from './types';
import { STATIONS } from './constants';
import AudioEngine, { AudioEngineHandle } from './components/AudioEngine';
import Visualizer from './components/Visualizer';

const App: React.FC = () => {
  const [currentStation, setCurrentStation] = useState<RadioStation>(STATIONS[0]);
  const [playerState, setPlayerState] = useState<PlayerState>(PlayerState.IDLE);
  const [volume, setVolume] = useState(0.8);
  const [isMuted, setIsMuted] = useState(false);
  const [analyser, setAnalyser] = useState<AnalyserNode | null>(null);

  const audioEngineRef = useRef<AudioEngineHandle>(null);

  const handleStationSelect = (station: RadioStation) => {
    setCurrentStation(station);
    // Auto-play when switching station if already playing or explicitly starting
    setTimeout(() => {
        audioEngineRef.current?.play();
    }, 100);
  };

  const handleTogglePlay = useCallback(() => {
    audioEngineRef.current?.toggle();
  }, []);

  return (
    <div className="flex flex-col h-screen w-full bg-slate-950 text-white font-sans overflow-hidden">
      {/* Header */}
      <header className="p-6 flex items-center justify-between border-b border-slate-800 bg-slate-900/50 backdrop-blur-md sticky top-0 z-10">
        <div>
          <h1 className="text-xl font-bold tracking-tight text-red-500">Radio Streamer</h1>
          <p className="text-xs text-slate-400 font-medium">EMISIÓN EN DIRECTO</p>
        </div>
        <div className="w-8 h-8 rounded-full bg-red-500 animate-pulse flex items-center justify-center shadow-lg shadow-red-500/20">
            <div className="w-3 h-3 rounded-full bg-white"></div>
        </div>
      </header>

      {/* Main Content (Scrollable List) */}
      <main className="flex-1 overflow-y-auto p-4 space-y-4 pb-48">
        <section>
          <h2 className="text-sm font-semibold text-slate-500 uppercase tracking-widest mb-3 ml-1">Tus Emisoras</h2>
          <div className="space-y-3">
            {STATIONS.map((station) => (
              <button
                key={station.id}
                onClick={() => handleStationSelect(station)}
                className={`w-full flex items-center p-4 rounded-2xl transition-all duration-300 border-2 ${
                  currentStation.id === station.id 
                    ? 'bg-slate-800 border-red-500 shadow-xl shadow-red-500/10' 
                    : 'bg-slate-900 border-transparent hover:bg-slate-800/50'
                }`}
              >
                <div className="relative w-14 h-14 rounded-xl overflow-hidden flex-shrink-0 shadow-lg">
                  <img src={station.image} alt={station.name} className="w-full h-full object-cover" />
                  {currentStation.id === station.id && playerState === PlayerState.PLAYING && (
                    <div className="absolute inset-0 bg-red-500/40 flex items-center justify-center">
                        <div className="flex gap-1 items-end h-4">
                            <div className="w-1 bg-white animate-[bounce_0.6s_infinite] h-2"></div>
                            <div className="w-1 bg-white animate-[bounce_0.8s_infinite] h-4"></div>
                            <div className="w-1 bg-white animate-[bounce_0.7s_infinite] h-3"></div>
                        </div>
                    </div>
                  )}
                </div>
                <div className="ml-4 text-left flex-1">
                  <h3 className={`font-bold ${currentStation.id === station.id ? 'text-white' : 'text-slate-200'}`}>
                    {station.name}
                  </h3>
                  <p className="text-xs text-slate-400 mt-0.5 line-clamp-1">{station.description}</p>
                </div>
                {currentStation.id === station.id && (
                  <div className="text-red-500">
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="currentColor"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 14.5v-9l6 4.5-6 4.5z"/></svg>
                  </div>
                )}
              </button>
            ))}
          </div>
        </section>

        {/* Info card */}
        <div className="p-6 bg-gradient-to-br from-slate-900 to-slate-800 rounded-3xl border border-slate-700/50 shadow-2xl mt-4">
            <h4 className="text-red-500 font-bold mb-2">Ayuda</h4>
            <p className="text-sm text-slate-300 leading-relaxed">
                Pulsa en una emisora para seleccionarla. El reproductor inferior te permite controlar el volumen y la reproducción.
            </p>
        </div>
      </main>

      {/* Persistent Player Controls (Sticky Bottom) */}
      <div className="fixed bottom-0 left-0 right-0 bg-slate-900/90 backdrop-blur-xl border-t border-slate-800 p-6 safe-bottom shadow-[0_-20px_50px_rgba(0,0,0,0.5)]">
        <div className="max-w-md mx-auto">
          {/* Visualizer Overlay */}
          <div className="mb-4">
             <Visualizer 
                analyser={analyser} 
                color={currentStation.color} 
                isPaused={playerState !== PlayerState.PLAYING} 
             />
          </div>

          <div className="flex items-center justify-between gap-4">
            {/* Current Playing Info */}
            <div className="flex-1 min-w-0">
              <h2 className="font-bold text-lg truncate leading-tight">{currentStation.name}</h2>
              <div className="flex items-center gap-2 mt-1">
                <span className={`w-2 h-2 rounded-full ${playerState === PlayerState.PLAYING ? 'bg-green-500 animate-pulse' : 'bg-slate-600'}`}></span>
                <p className="text-xs font-semibold text-slate-400 uppercase tracking-tighter">
                  {playerState === PlayerState.LOADING ? 'Cargando stream...' : playerState === PlayerState.PLAYING ? 'Al aire' : 'En pausa'}
                </p>
              </div>
            </div>

            {/* Play/Pause Button */}
            <button
              onClick={handleTogglePlay}
              className={`w-16 h-16 rounded-full flex items-center justify-center transition-all duration-300 shadow-2xl ${
                playerState === PlayerState.LOADING ? 'bg-slate-700 cursor-not-allowed' : 'bg-red-500 hover:scale-105 active:scale-95'
              }`}
              disabled={playerState === PlayerState.LOADING}
            >
              {playerState === PlayerState.LOADING ? (
                <svg className="animate-spin h-8 w-8 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
              ) : playerState === PlayerState.PLAYING ? (
                <svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" fill="currentColor" viewBox="0 0 24 24"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>
              ) : (
                <svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" fill="currentColor" viewBox="0 0 24 24" className="ml-1"><path d="M8 5v14l11-7z"/></svg>
              )}
            </button>
          </div>

          {/* Volume Slider */}
          <div className="mt-6 flex items-center gap-3">
            <button onClick={() => setIsMuted(!isMuted)} className="text-slate-400">
              {isMuted || volume === 0 ? (
                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" fill="currentColor" viewBox="0 0 24 24"><path d="M16.5 12c0-1.77-1.02-3.29-2.5-4.03v8.05c1.48-.73 2.5-2.25 2.5-4.02zM14 3.23v2.06c2.89.86 5 3.54 5 6.71s-2.11 5.85-5 6.71v2.06c4.01-.91 7-4.49 7-8.77s-2.99-7.86-7-8.77zM3 9v6h4l5 5V4L7 9H3z"/></svg>
              ) : (
                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" fill="currentColor" viewBox="0 0 24 24"><path d="M3 9v6h4l5 5V4L7 9H3zm13.5 3c0-1.77-1.02-3.29-2.5-4.03v8.05c1.48-.73 2.5-2.25 2.5-4.02zM14 3.23v2.06c2.89.86 5 3.54 5 6.71s-2.11 5.85-5 6.71v2.06c4.01-.91 7-4.49 7-8.77s-2.99-7.86-7-8.77z"/></svg>
              )}
            </button>
            <input
              type="range"
              min="0"
              max="1"
              step="0.01"
              value={volume}
              onChange={(e) => setVolume(parseFloat(e.target.value))}
              className="flex-1 h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-red-500"
            />
          </div>
        </div>
      </div>

      {/* Hidden Audio Engine */}
      <AudioEngine
        ref={audioEngineRef}
        url={currentStation.url}
        volume={volume}
        isMuted={isMuted}
        onStateChange={setPlayerState}
        onAnalyserCreated={setAnalyser}
      />
    </div>
  );
};

export default App;

import React, { useState, useRef, useCallback } from 'react';
import { PlayerState, RadioStation } from './types';
import { STATIONS } from './constants';
import AudioEngine, { AudioEngineHandle } from './components/AudioEngine';
import Visualizer from './components/Visualizer';

const App: React.FC = () => {
  const [currentStation, setCurrentStation] = useState<RadioStation>(STATIONS[0]);
  const [playerState, setPlayerState] = useState<PlayerState>(PlayerState.IDLE);
  const [volume, setVolume] = useState(0.8);
  const [isMuted, setIsMuted] = useState(false);
  const [analyser, setAnalyser] = useState<AnalyserNode | null>(null);

  const audioEngineRef = useRef<AudioEngineHandle>(null);

  const handleStationChange = (event: React.ChangeEvent<HTMLSelectElement>) => {
    const stationId = event.target.value;
    const station = STATIONS.find(s => s.id === stationId);
    if (station) {
      setCurrentStation(station);
      // Brief delay to ensure state updates before play command
      setTimeout(() => {
        audioEngineRef.current?.play();
      }, 50);
    }
  };

  const handleTogglePlay = useCallback(() => {
    audioEngineRef.current?.toggle();
  }, []);

  return (
    <div className="flex flex-col h-screen w-full bg-slate-950 text-white font-sans overflow-hidden">
      {/* Header */}
      <header className="p-6 flex flex-col items-center justify-center border-b border-slate-800 bg-slate-900/80 backdrop-blur-md sticky top-0 z-20">
        <h1 className="text-2xl font-black tracking-tighter text-red-500 uppercase italic">RNE EMISORAS</h1>
        <div className="flex items-center gap-2 mt-1">
          <div className="w-2 h-2 rounded-full bg-red-600 animate-pulse"></div>
          <span className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.2em]">Live Radio Player</span>
        </div>
      </header>

      {/* Main Player Display */}
      <main className="flex-1 flex flex-col items-center justify-center p-8 space-y-8">

        {/* Album Art / Station Image */}
        <div className="relative group">
          <div 
            className="absolute -inset-4 bg-gradient-to-r from-red-600 to-blue-600 rounded-[2.5rem] blur-2xl opacity-20 group-hover:opacity-40 transition-opacity duration-700"
            style={{ backgroundColor: currentStation.color + '44' }}
          ></div>
          <div className="relative w-64 h-64 md:w-80 md:h-80 rounded-[2rem] overflow-hidden shadow-2xl border-4 border-slate-800/50">
            <img 
              src={currentStation.image} 
              alt={currentStation.name} 
              className={`w-full h-full object-cover transition-transform duration-[3s] ${playerState === PlayerState.PLAYING ? 'scale-110' : 'scale-100'}`}
            />
            {playerState === PlayerState.LOADING && (
              <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center">
                <div className="w-12 h-12 border-4 border-red-500 border-t-transparent rounded-full animate-spin"></div>
              </div>
            )}
          </div>
        </div>

        {/* Station Details */}
        <div className="text-center space-y-2 max-w-xs">
          <h2 className="text-3xl font-bold tracking-tight">{currentStation.name}</h2>
          <p className="text-slate-400 text-sm font-medium h-10 overflow-hidden leading-relaxed">
            {currentStation.description}
          </p>
        </div>

        {/* Custom Dropdown Selector */}
        <div className="w-full max-w-xs relative">
          <label htmlFor="station-select" className="block text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2 ml-1">
            Seleccionar Emisora
          </label>
          <div className="relative">
            <select
              id="station-select"
              value={currentStation.id}
              onChange={handleStationChange}
              className="w-full bg-slate-900 border-2 border-slate-800 text-white py-4 px-5 rounded-2xl appearance-none focus:outline-none focus:border-red-500 transition-colors font-semibold shadow-xl"
            >
              {STATIONS.map((station) => (
                <option key={station.id} value={station.id}>
                  {station.name}
                </option>
              ))}
            </select>
            <div className="absolute right-5 top-1/2 -translate-y-1/2 pointer-events-none text-slate-500">
              <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3">
                <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" />
              </svg>
            </div>
          </div>
        </div>
      </main>

      {/* Playback Controls & Visualizer */}
      <footer className="bg-slate-900/95 backdrop-blur-2xl border-t border-slate-800 p-8 safe-bottom shadow-[0_-30px_60px_rgba(0,0,0,0.6)]">
        <div className="max-w-md mx-auto flex flex-col items-center">

          <div className="w-full mb-8">
            <Visualizer 
              analyser={analyser} 
              color={currentStation.color} 
              isPaused={playerState !== PlayerState.PLAYING} 
            />
          </div>

          <div className="w-full flex items-center justify-between gap-6">
            {/* Volume Icon Button */}
            <button 
              onClick={() => setIsMuted(!isMuted)} 
              className={`p-3 rounded-full transition-colors ${isMuted ? 'text-red-500 bg-red-500/10' : 'text-slate-400 hover:text-white'}`}
            >
              {isMuted || volume === 0 ? (
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" viewBox="0 0 24 24"><path d="M16.5 12c0-1.77-1.02-3.29-2.5-4.03v8.05c1.48-.73 2.5-2.25 2.5-4.02zM14 3.23v2.06c2.89.86 5 3.54 5 6.71s-2.11 5.85-5 6.71v2.06c4.01-.91 7-4.49 7-8.77s-2.99-7.86-7-8.77zM3 9v6h4l5 5V4L7 9H3z"/></svg>
              ) : (
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" viewBox="0 0 24 24"><path d="M3 9v6h4l5 5V4L7 9H3zm13.5 3c0-1.77-1.02-3.29-2.5-4.03v8.05c1.48-.73 2.5-2.25 2.5-4.02zM14 3.23v2.06c2.89.86 5 3.54 5 6.71s-2.11 5.85-5 6.71v2.06c4.01-.91 7-4.49 7-8.77s-2.99-7.86-7-8.77z"/></svg>
              )}
            </button>

            {/* Large Play/Pause */}
            <button
              onClick={handleTogglePlay}
              className={`w-20 h-20 rounded-full flex items-center justify-center transition-all duration-300 shadow-2xl relative group ${
                playerState === PlayerState.LOADING ? 'bg-slate-800 cursor-not-allowed' : 'bg-white text-black hover:scale-110 active:scale-95'
              }`}
              disabled={playerState === PlayerState.LOADING}
            >
              <div className="absolute -inset-2 bg-white/20 rounded-full blur group-hover:blur-md transition-all"></div>
              {playerState === PlayerState.LOADING ? (
                <div className="w-10 h-10 border-4 border-slate-600 border-t-white rounded-full animate-spin"></div>
              ) : playerState === PlayerState.PLAYING ? (
                <svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" fill="currentColor" viewBox="0 0 24 24"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>
              ) : (
                <svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" fill="currentColor" viewBox="0 0 24 24" className="ml-1"><path d="M8 5v14l11-7z"/></svg>
              )}
            </button>

            {/* Status indicator */}
            <div className="p-3 text-slate-500 uppercase font-black text-[10px] tracking-widest text-right">
              {playerState === PlayerState.PLAYING ? 'ON AIR' : playerState === PlayerState.LOADING ? 'SYNC' : 'OFF'}
            </div>
          </div>

          {/* Volume Slider */}
          <div className="mt-8 w-full">
            <input
              type="range"
              min="0"
              max="1"
              step="0.01"
              value={volume}
