import React, { useEffect, useRef } from 'react';
import { select } from 'd3';

interface VisualizerProps {
  analyser: AnalyserNode | null;
  color: string;
  isPaused: boolean;
}

const Visualizer: React.FC<VisualizerProps> = ({ analyser, color, isPaused }) => {
  const svgRef = useRef<SVGSVGElement>(null);

  useEffect(() => {
    if (!svgRef.current || !analyser) return;

    const svg = select(svgRef.current);
    const width = svgRef.current.clientWidth;
    const height = svgRef.current.clientHeight;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    // Diseño vanguardista: más barras, más finas, estilo digital de alta precisión
    const barCount = 64;
    const barWidth = (width / barCount) * 0.7;
    let animationId: number;

    // Crear gradiente para las barras
    const defs = svg.append('defs');
    const gradient = defs.append('linearGradient')
      .attr('id', 'barGradient')
      .attr('x1', '0%').attr('y1', '100%')
      .attr('x2', '0%').attr('y2', '0%');

    gradient.append('stop').attr('offset', '0%').attr('stop-color', color).attr('stop-opacity', 0.2);
    gradient.append('stop').attr('offset', '70%').attr('stop-color', color).attr('stop-opacity', 0.8);
    gradient.append('stop').attr('offset', '100%').attr('stop-color', '#fff').attr('stop-opacity', 1);

    const draw = () => {
      animationId = requestAnimationFrame(draw);
      analyser.getByteFrequencyData(dataArray);

      // Usamos una porción del espectro más representativa para radio
      const spectrum = Array.from(dataArray).slice(0, barCount);

      const bars = svg.selectAll('rect')
        .data(spectrum);

      bars.enter()
        .append('rect')
        .merge(bars as any)
        .attr('x', (d, i) => i * (width / barCount))
        .attr('y', d => height - (d / 255) * height)
        .attr('width', barWidth)
        .attr('height', d => Math.max((d / 255) * height, 2)) // Mínimo de 2px para que se vea la señal
        .attr('fill', isPaused ? 'rgba(100,100,100,0.2)' : 'url(#barGradient)')
        .attr('rx', 0.5);

      bars.exit().remove();
    };

    draw();

    return () => {
      cancelAnimationFrame(animationId);
      svg.selectAll('*').remove();
    };
  }, [analyser, color, isPaused]);

  return (
    <div className="w-full h-full flex items-center justify-center p-1">
      <svg ref={svgRef} className="w-full h-full overflow-visible" />
    </div>
  );
};

export default Visualizer;

