import React, { useEffect, useRef } from 'react';
import { select } from 'd3';

interface VisualizerProps {
  analyser: AnalyserNode | null;
  color: string;
  isPaused: boolean;
}

const Visualizer: React.FC<VisualizerProps> = ({ analyser, color, isPaused }) => {
  const svgRef = useRef<SVGSVGElement>(null);

  useEffect(() => {
    if (!svgRef.current || !analyser) return;

    const svg = select(svgRef.current);
    const width = svgRef.current.clientWidth;
    const height = svgRef.current.clientHeight;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    const barCount = 40; 
    const barWidth = (width / barCount) * 0.6;
    let animationId: number;

    const defs = svg.append('defs');
    const gradient = defs.append('linearGradient')
      .attr('id', 'neonGradient')
      .attr('x1', '0%').attr('y1', '100%')
      .attr('x2', '0%').attr('y2', '0%');

    gradient.append('stop').attr('offset', '0%').attr('stop-color', '#06B6D4');
    gradient.append('stop').attr('offset', '50%').attr('stop-color', '#D946EF');
    gradient.append('stop').attr('offset', '100%').attr('stop-color', '#84CC16');

    const draw = () => {
      animationId = requestAnimationFrame(draw);
      analyser.getByteFrequencyData(dataArray);

      const spectrum = Array.from(dataArray).slice(0, barCount);

      const bars = svg.selectAll('rect')
        .data(spectrum);

      bars.enter()
        .append('rect')
        .merge(bars as any)
        .attr('x', (d, i) => i * (width / barCount) + (width / barCount - barWidth) / 2)
        .attr('y', d => height - (d / 255) * height)
        .attr('width', barWidth)
        .attr('height', d => Math.max((d / 255) * height, 4))
        .attr('fill', isPaused ? 'rgba(255,255,255,0.1)' : 'url(#neonGradient)')
        .attr('rx', barWidth / 2)
        .attr('style', isPaused ? '' : 'filter: drop-shadow(0 0 4px rgba(6, 182, 212, 0.4))');

      bars.exit().remove();
    };

    draw();

    return () => {
      cancelAnimationFrame(animationId);
      svg.selectAll('*').remove();
    };
  }, [analyser, color, isPaused]);

  return (
    <div className="w-full h-full flex items-center justify-center">
      <svg ref={svgRef} className="w-full h-full overflow-visible" />
    </div>
  );
};

