import React, { useEffect, useRef } from 'react';
import { select } from 'd3';

interface VisualizerProps {
  analyser: AnalyserNode | null;
  color: string;
  isPaused: boolean;
}

const Visualizer: React.FC<VisualizerProps> = ({ analyser, color, isPaused }) => {
  const svgRef = useRef<SVGSVGElement>(null);

  useEffect(() => {
    if (!svgRef.current || !analyser) return;

    const svg = select(svgRef.current);
    const width = svgRef.current.clientWidth;
    const height = svgRef.current.clientHeight;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    const barCount = 18; 
    const barWidth = width / barCount - 1;
    let animationId: number;

    const draw = () => {
      animationId = requestAnimationFrame(draw);
      analyser.getByteFrequencyData(dataArray);

      // Usar solo las frecuencias bajas y medias para que sea más activo visualmente
      const spectrum = Array.from(dataArray).slice(0, barCount);

      const bars = svg.selectAll('rect')
        .data(spectrum);

      bars.enter()
        .append('rect')
        .merge(bars as any)
        .attr('x', (d, i) => i * (width / barCount))
        .attr('y', d => height - (d / 255) * height)
        .attr('width', barWidth)
        .attr('height', d => Math.max((d / 255) * height, 1))
        .attr('fill', (d, i) => {
          if (isPaused) return '#111';
          const h = (d / 255) * 100;
          if (h > 80) return '#ff0000'; // Rojo
          if (h > 50) return '#ffff00'; // Amarillo
          return '#00ff00'; // Verde Winamp
        })
        .attr('shape-rendering', 'crispEdges'); // Estilo pixelado

      bars.exit().remove();
    };

    draw();

    return () => {
      cancelAnimationFrame(animationId);
      svg.selectAll('*').remove();
    };
  }, [analyser, color, isPaused]);

  return (
    <div className="w-full h-full flex items-center justify-center bg-black">
      <svg ref={svgRef} className="w-full h-full" />
    </div>
  );
};

export default Visualizer;

import React, { useState, useRef, useCallback, useEffect } from 'react';
import { PlayerState, RadioStation } from './types';
import { STATIONS } from './constants';
import AudioEngine, { AudioEngineHandle } from './components/AudioEngine';
import Visualizer from './components/Visualizer';

const App: React.FC = () => {
  const [currentStation, setCurrentStation] = useState<RadioStation>(STATIONS[0]);
  const [playerState, setPlayerState] = useState<PlayerState>(PlayerState.IDLE);
  const [volume, setVolume] = useState(0.8);
  const [isMuted, setIsMuted] = useState(false);
  const [analyser, setAnalyser] = useState<AnalyserNode | null>(null);
  const [currentTime, setCurrentTime] = useState('00:00');

  const audioEngineRef = useRef<AudioEngineHandle>(null);

  // Simulador de tiempo (Winamp cuenta tiempo transcurrido)
  useEffect(() => {
    let interval: any;
    let seconds = 0;
    if (playerState === PlayerState.PLAYING) {
      interval = setInterval(() => {
        seconds++;
        const mins = Math.floor(seconds / 60).toString().padStart(2, '0');
        const secs = (seconds % 60).toString().padStart(2, '0');
        setCurrentTime(`${mins}:${secs}`);
      }, 1000);
    } else if (playerState === PlayerState.IDLE || playerState === PlayerState.LOADING) {
      setCurrentTime('00:00');
      seconds = 0;
    }
    return () => clearInterval(interval);
  }, [playerState]);

  const handleStationClick = (station: RadioStation) => {
    if (currentStation.id === station.id && playerState === PlayerState.PLAYING) {
      audioEngineRef.current?.pause();
    } else {
      setCurrentStation(station);
      setTimeout(() => {
        audioEngineRef.current?.play();
      }, 50);
    }
  };

  const handleTogglePlay = useCallback(() => {
    audioEngineRef.current?.toggle();
  }, []);

  const handleStop = () => {
    audioEngineRef.current?.pause();
    // En Winamp el Stop resetea
  };

  const handleNext = () => {
    const idx = STATIONS.findIndex(s => s.id === currentStation.id);
    const nextIdx = (idx + 1) % STATIONS.length;
    handleStationClick(STATIONS[nextIdx]);
  };

  const handlePrev = () => {
    const idx = STATIONS.findIndex(s => s.id === currentStation.id);
