import React, { useEffect, useRef } from 'react';
import { select } from 'd3';

interface VisualizerProps {
  analyser: AnalyserNode | null;
  color: string;
  isPaused: boolean;
}

const Visualizer: React.FC<VisualizerProps> = ({ analyser, color, isPaused }) => {
  const svgRef = useRef<SVGSVGElement>(null);

  useEffect(() => {
    if (!svgRef.current || !analyser) return;

    const svg = select(svgRef.current);
    const width = svgRef.current.clientWidth;
    const height = svgRef.current.clientHeight;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    const barCount = 40; 
    const barWidth = width / barCount;
    let animationId: number;

    const draw = () => {
      animationId = requestAnimationFrame(draw);
      analyser.getByteFrequencyData(dataArray);

      const spectrum = Array.from(dataArray).slice(0, barCount);

      const bars = svg.selectAll('rect')
        .data(spectrum);

      bars.enter()
        .append('rect')
        .merge(bars as any)
        .attr('x', (d, i) => i * barWidth)
        .attr('y', d => height - (d / 255) * height)
        .attr('width', barWidth - 1)
        .attr('height', d => (d / 255) * height)
        .attr('fill', isPaused ? 'transparent' : color)
        .style('opacity', 0.6);

      bars.exit().remove();
    };

    draw();

    return () => {
      cancelAnimationFrame(animationId);
      svg.selectAll('*').remove();
    };
  }, [analyser, color, isPaused]);

  return (
    <div className="w-full h-full opacity-80">
      <svg ref={svgRef} className="w-full h-full" />
    </div>
  );
};

export default Visualizer;

