import React, { useEffect, useRef } from 'react';
import { select } from 'd3';

interface VisualizerProps {
  analyser: AnalyserNode | null;
  color: string;
  isPaused: boolean;
}

const Visualizer: React.FC<VisualizerProps> = ({ analyser, color, isPaused }) => {
  const svgRef = useRef<SVGSVGElement>(null);

  useEffect(() => {
    if (!svgRef.current || !analyser) return;

    const svg = select(svgRef.current);
    const width = svgRef.current.clientWidth;
    const height = svgRef.current.clientHeight;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    const barCount = 32; // More bars for a "full" look
    const barWidth = (width - 20) / barCount; // Leave space for VU bars
    let animationId: number;

    const draw = () => {
      animationId = requestAnimationFrame(draw);
      analyser.getByteFrequencyData(dataArray);

      // Data for Spectrum
      const spectrum = Array.from(dataArray).slice(0, barCount);

      // Calculate VU Level (Average of lower frequencies for punchiness)
      const lowFreqs = dataArray.slice(0, 10);
      const avgLevel = lowFreqs.reduce((a, b) => a + b, 0) / lowFreqs.length;

      // We'll draw 2 VU bars on the sides and the spectrum in the middle
      const vuData = [avgLevel, avgLevel * 0.9]; // Simulated L/R

      // --- Draw Spectrum ---
      const bars = svg.selectAll('rect.spec')
        .data(spectrum);

      bars.enter()
        .append('rect')
        .attr('class', 'spec')
        .merge(bars as any)
        .attr('x', (d, i) => 10 + i * barWidth)
        .attr('y', d => height - (d / 255) * height)
        .attr('width', Math.max(1, barWidth - 1))
        .attr('height', d => (d / 255) * height)
        .attr('fill', (d) => {
           if (isPaused) return '#111';
           const val = d as number;
           if (val > 200) return '#ff0000';
           if (val > 140) return '#ffff00';
           return '#00ff00';
        });

      bars.exit().remove();

      // --- Draw VU Bars (L & R) ---
      const vus = svg.selectAll('rect.vu')
        .data(vuData);

      vus.enter()
        .append('rect')
        .attr('class', 'vu')
        .merge(vus as any)
        .attr('x', (d, i) => i === 0 ? 2 : width - 7)
        .attr('y', d => height - (d / 255) * height)
        .attr('width', 5)
        .attr('height', d => (d / 255) * height)
        .attr('fill', (d) => {
           if (isPaused) return '#111';
           const val = d as number;
           if (val > 180) return '#ff3333';
           return '#00ee00';
        });

      vus.exit().remove();
    };

    draw();

    return () => {
      cancelAnimationFrame(animationId);
      svg.selectAll('*').remove();
    };
  }, [analyser, color, isPaused]);

  return (
    <div className="w-full h-full bg-black/40">
      <svg ref={svgRef} className="w-full h-full" />
    </div>
  );
};

export default Visualizer;

