import React, { useEffect, useRef } from 'react';

interface VisualizerProps {
  analyser: AnalyserNode | null;
  color: string;
  isPaused: boolean;
}

const Visualizer: React.FC<VisualizerProps> = ({ analyser, isPaused }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (!canvasRef.current || !analyser) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    let animationId: number;

    // Smooth needle movement
    let leftNeedlePos = 0;
    let rightNeedlePos = 0;

    const draw = () => {
      animationId = requestAnimationFrame(draw);
      analyser.getByteFrequencyData(dataArray);

      const width = canvas.width;
      const height = canvas.height;

      // Clear with a slight fade for motion trail (optional, but here we clear fully)
      ctx.fillStyle = '#0a0a0a';
      ctx.fillRect(0, 0, width, height);

      // Calculate levels
      // We use different parts of the spectrum to simulate L/R movement
      const leftLevel = dataArray.slice(0, 10).reduce((a, b) => a + b, 0) / 10;
      const rightLevel = dataArray.slice(10, 20).reduce((a, b) => a + b, 0) / 10;

      // Smoothing
      const targetLeft = isPaused ? 0 : (leftLevel / 255);
      const targetRight = isPaused ? 0 : (rightLevel / 255);

      leftNeedlePos += (targetLeft - leftNeedlePos) * 0.2;
      rightNeedlePos += (targetRight - rightNeedlePos) * 0.15;

      const drawGauge = (x: number, y: number, w: number, h: number, pos: number, label: string) => {
        const centerX = x + w / 2;
        const centerY = y + h * 0.9;
        const radius = h * 0.8;

        // Draw Gauge Background (The Arc)
        ctx.beginPath();
        ctx.arc(centerX, centerY, radius, Math.PI * 1.1, Math.PI * 1.9);
        ctx.strokeStyle = '#333';
        ctx.lineWidth = 4;
        ctx.stroke();

        // Scale Ticks
        ctx.lineWidth = 1;
        for (let i = 0; i <= 10; i++) {
          const angle = Math.PI * 1.1 + (i / 10) * (Math.PI * 0.8);
          const innerR = radius - 5;
          const outerR = radius + 2;
          ctx.beginPath();
          ctx.moveTo(centerX + Math.cos(angle) * innerR, centerY + Math.sin(angle) * innerR);
          ctx.lineTo(centerX + Math.cos(angle) * outerR, centerY + Math.sin(angle) * outerR);
          ctx.strokeStyle = i > 7 ? '#ff0000' : '#888';
          ctx.stroke();
        }

        // Label
        ctx.fillStyle = '#666';
        ctx.font = '8px monospace';
        ctx.textAlign = 'center';
        ctx.fillText(label, centerX, centerY - radius * 0.3);

        // Draw Needle
        const needleAngle = Math.PI * 1.1 + pos * (Math.PI * 0.8);
        ctx.beginPath();
        ctx.moveTo(centerX, centerY);
        ctx.lineTo(centerX + Math.cos(needleAngle) * radius, centerY + Math.sin(needleAngle) * radius);
        ctx.strokeStyle = '#ff3300';
        ctx.lineWidth = 2;
        ctx.shadowBlur = 5;
        ctx.shadowColor = '#ff3300';
        ctx.stroke();
        ctx.shadowBlur = 0;

        // Needle Hub
        ctx.beginPath();
        ctx.arc(centerX, centerY, 4, 0, Math.PI * 2);
        ctx.fillStyle = '#222';
        ctx.fill();
        ctx.strokeStyle = '#444';
        ctx.stroke();
      };

      // Draw two gauges
      const margin = 10;
      const gaugeWidth = (width - margin * 3) / 2;
      drawGauge(margin, 5, gaugeWidth, height - 10, leftNeedlePos, 'LEFT CH');
      drawGauge(gaugeWidth + margin * 2, 5, gaugeWidth, height - 10, rightNeedlePos, 'RIGHT CH');

      // Add a subtle scanline or glass effect
      ctx.fillStyle = 'rgba(255, 255, 255, 0.02)';
      for (let i = 0; i < height; i += 2) {
        ctx.fillRect(0, i, width, 1);
      }
    };

    draw();

    return () => {
      cancelAnimationFrame(animationId);
    };
  }, [analyser, isPaused]);

  return (
    <div className="w-full h-full bg-black flex items-center justify-center p-1">
      <canvas 
        ref={canvasRef} 
        width={300} 
        height={80} 
        className="w-full h-full object-contain"
      />
    </div>
  );
};

export default Visualizer;

