import React, { useEffect, useRef } from 'react';

interface VisualizerProps {
  analyser: AnalyserNode | null;
  color: string;
  isPaused: boolean;
}

const Visualizer: React.FC<VisualizerProps> = ({ analyser, isPaused }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const peaksRef = useRef<number[]>(new Array(16).fill(0));

  useEffect(() => {
    if (!canvasRef.current || !analyser) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    let animationId: number;

    const draw = () => {
      animationId = requestAnimationFrame(draw);
      analyser.getByteFrequencyData(dataArray);

      const width = canvas.width;
      const height = canvas.height;

      // Fondo oscuro
      ctx.fillStyle = '#000';
      ctx.fillRect(0, 0, width, height);

      const barCount = 16;
      const barWidth = (width / barCount) - 2;
      const segments = 12;
      const segmentHeight = (height / segments) - 1;

      for (let i = 0; i < barCount; i++) {
        // Tomamos una muestra de frecuencia para esta barra
        const sampleIdx = Math.floor((i / barCount) * (bufferLength / 2));
        const val = isPaused ? 0 : dataArray[sampleIdx];
        const activeSegments = Math.ceil((val / 255) * segments);

        // Caída de picos
        if (activeSegments > peaksRef.current[i]) {
          peaksRef.current[i] = activeSegments;
        } else if (peaksRef.current[i] > 0) {
          peaksRef.current[i] -= 0.1;
        }

        for (let j = 0; j < segments; j++) {
          const x = i * (barWidth + 2);
          const y = height - (j + 1) * (segmentHeight + 1);

          const isActive = j < activeSegments;
          const isPeak = j === Math.floor(peaksRef.current[i]) && peaksRef.current[i] > 0;

          // Colores estilo LED
          if (isActive || isPeak) {
            if (j > segments * 0.8) ctx.fillStyle = '#ff0000'; // Rojo
            else if (j > segments * 0.6) ctx.fillStyle = '#ffff00'; // Amarillo
            else ctx.fillStyle = '#00ff00'; // Verde

            if (isPeak && !isActive) ctx.globalAlpha = 0.6;
            else ctx.globalAlpha = 1.0;
          } else {
            ctx.fillStyle = '#1a1a1a'; // LED apagado
            ctx.globalAlpha = 1.0;
          }

          ctx.fillRect(x, y, barWidth, segmentHeight);
        }
      }
      ctx.globalAlpha = 1.0;
    };

    draw();

    return () => {
      cancelAnimationFrame(animationId);
    };
  }, [analyser, isPaused]);

  return (
    <div className="w-full h-full flex items-center justify-center bg-black">
      <canvas 
        ref={canvasRef} 
        width={300} 
        height={100} 
        className="w-full h-full object-fill"
      />
    </div>
  );
};

export default Visualizer;

