import React, { useEffect, useRef } from 'react';

interface VisualizerProps {
  analyser: AnalyserNode | null;
  color: string;
  isPaused: boolean;
}

const Visualizer: React.FC<VisualizerProps> = ({ analyser, isPaused }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const peaksRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });

  useEffect(() => {
    if (!canvasRef.current || !analyser) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    let animationId: number;

    const draw = () => {
      animationId = requestAnimationFrame(draw);
      analyser.getByteFrequencyData(dataArray);

      const width = canvas.width;
      const height = canvas.height;

      // Fondo ultra oscuro con ligero gradiente
      ctx.fillStyle = '#050505';
      ctx.fillRect(0, 0, width, height);

      // --- ANALIZADOR DE ESPECTRO FONDO ---
      // Dibujamos el espectro completo de fondo de forma sutil
      const barCount = 32;
      const barWidth = (width / barCount);

      ctx.globalAlpha = 0.2;
      for (let i = 0; i < barCount; i++) {
        const val = isPaused ? 0 : dataArray[Math.floor(i * (bufferLength / barCount))];
        const h = (val / 255) * (height * 0.7);
        ctx.fillStyle = '#006600';
        ctx.fillRect(i * barWidth, height - h - 5, barWidth - 1, h);
      }
      ctx.globalAlpha = 1.0;

      // --- AJUSTE DE CANALES L/R ---
      // Simulamos canales L/R con mayor rango de frecuencias para que sean más reactivos
      // Canal Izquierdo: Frecuencias bajas y medias (primer tercio del buffer)
      const leftSlice = dataArray.slice(0, Math.floor(bufferLength * 0.4));
      const leftVal = isPaused ? 0 : leftSlice.reduce((a, b) => a + b, 0) / leftSlice.length;

      // Canal Derecho: Frecuencias medias y altas (segundo y último tercio del buffer)
      // Aplicamos un pequeño multiplicador (1.2) para compensar la menor energía en frecuencias altas
      const rightSlice = dataArray.slice(Math.floor(bufferLength * 0.4), bufferLength);
      const rightValRaw = isPaused ? 0 : rightSlice.reduce((a, b) => a + b, 0) / rightSlice.length;
      const rightVal = Math.min(255, rightValRaw * 1.5);

      const drawMeter = (y: number, value: number, peakKey: 'left' | 'right', label: string) => {
        const meterWidth = width - 45;
        const fillWidth = (value / 255) * meterWidth;

        // Caída de pico (suavizada)
        if (value > peaksRef.current[peakKey]) {
          peaksRef.current[peakKey] = value;
        } else {
          peaksRef.current[peakKey] *= 0.97;
        }
        const peakPos = (peaksRef.current[peakKey] / 255) * meterWidth;

        // Etiqueta Canal
        ctx.fillStyle = '#888';
        ctx.font = 'bold 7px "Orbitron", sans-serif';
        ctx.fillText(label, 5, y + 8);

        // Fondo del carril
        ctx.fillStyle = '#111';
        ctx.fillRect(35, y, meterWidth, 10);

        // Gradiente de la barra (Verde -> Amarillo -> Rojo)
        const grad = ctx.createLinearGradient(35, 0, 35 + meterWidth, 0);
        grad.addColorStop(0, '#00ff00');
        grad.addColorStop(0.6, '#00ff00');
        grad.addColorStop(0.8, '#ffff00');
        grad.addColorStop(0.95, '#ff0000');

        ctx.fillStyle = grad;
        ctx.fillRect(35, y, fillWidth, 10);

        // Marcador de pico (Línea blanca/roja)
        ctx.fillStyle = peaksRef.current[peakKey] > 220 ? '#ff0000' : '#ffffff';
        ctx.fillRect(35 + peakPos, y, 2, 10);

        // Divisiones de escala
        ctx.strokeStyle = 'rgba(0,0,0,0.6)';
        ctx.lineWidth = 1;
        for (let i = 1; i < 10; i++) {
          const xPos = 35 + (i / 10) * meterWidth;
          ctx.beginPath();
          ctx.moveTo(xPos, y);
          ctx.lineTo(xPos, y + 10);
          ctx.stroke();
        }
      };

      // Posicionamiento de los vúmetros
      drawMeter(12, leftVal, 'left', 'CH-L');
      drawMeter(28, rightVal, 'right', 'CH-R');

      // Efecto de Scanlines Digitales
      ctx.fillStyle = 'rgba(0, 255, 0, 0.02)';
      for (let i = 0; i < height; i += 3) {
        ctx.fillRect(0, i, width, 1);
      }
    };

    draw();

    return () => {
      cancelAnimationFrame(animationId);
    };
  }, [analyser, isPaused]);

  return (
    <div className="w-full h-full flex items-center justify-center bg-black">
      <canvas 
        ref={canvasRef} 
        width={320} 
        height={50} 
        className="w-full h-full object-contain"
      />
    </div>
  );
};

