      analyser.getByteFrequencyData(dataArray);

      const width = canvas.width;
      const height = canvas.height;

      // Fondo ultra oscuro
      ctx.fillStyle = '#050505';
      ctx.fillRect(0, 0, width, height);

      // --- ANALIZADOR DE ESPECTRO SUTIL (FONDO) ---
      const barCount = 32;
      const barWidth = (width / barCount);

      ctx.globalAlpha = 0.15;
      for (let i = 0; i < barCount; i++) {
        const idx = Math.floor(i * (bufferLength / barCount));
        const val = isPaused ? 0 : dataArray[idx];
        const h = (val / 255) * (height * 0.75);
        ctx.fillStyle = '#008800';
        ctx.fillRect(i * barWidth, height - h - 5, barWidth - 1, h);
      }
      ctx.globalAlpha = 1.0;

      // --- BALANCE DE CANALES L/R (RECALIBRADO) ---
      // En transmisiones digitales, la mayor energía reside en las frecuencias bajas.
      // Para equilibrar visualmente R con L, seleccionamos rangos que capturen 
      // la mayor intensidad posible en ambos lados del espectro visible.

      // Canal Izquierdo (L): Enfocado en Sub-graves y Graves (Bins 1 a 10)
      const leftSlice = dataArray.slice(1, 12);
      const leftVal = isPaused ? 0 : leftSlice.reduce((a, b) => Math.max(a, b), 0);

      // Canal Derecho (R): Enfocado en Medios-Bajos y Medios (Bins 4 a 20)
      // Usamos un rango que se solapa y capturamos el valor máximo para mayor reactividad
      const rightSlice = dataArray.slice(5, 25);
      const rightValRaw = isPaused ? 0 : rightSlice.reduce((a, b) => Math.max(a, b), 0);

      // Compensación de balance: Las frecuencias medias suelen tener un -20% de amplitud 
      // respecto a los graves en señales masterizadas. Aplicamos un factor de corrección suave.
      const rightVal = Math.min(255, rightValRaw * 1.15);

      const drawMeter = (y: number, value: number, peakKey: 'left' | 'right', label: string) => {
        const meterPadding = 45;
        const meterWidth = width - meterPadding;
        const fillWidth = (value / 255) * meterWidth;

        // Caída de pico balística (Estilo PPM - Peak Programme Meter)
        if (value > peaksRef.current[peakKey]) {
          peaksRef.current[peakKey] = value;
        } else {
          // Caída lenta para que el ojo pueda seguir el ritmo
          peaksRef.current[peakKey] -= 2.5;
          if (peaksRef.current[peakKey] < 0) peaksRef.current[peakKey] = 0;
        }
        const peakPos = (peaksRef.current[peakKey] / 255) * meterWidth;

        // Texto del Canal
        ctx.fillStyle = '#aaa';
        ctx.font = 'bold 8px "Orbitron", sans-serif';
        ctx.fillText(label, 6, y + 8);

        // Fondo del carril con efecto de profundidad
        ctx.fillStyle = '#111';
        ctx.fillRect(38, y, meterWidth, 10);

        // Dibujamos segmentos para un look más "digital rack"
        const segments = 40;
        const segWidth = meterWidth / segments;

        for(let i = 0; i < segments; i++) {
          const segX = 38 + (i * segWidth);
          const isFull = (i / segments) * meterWidth < fillWidth;

          if (isFull) {
            // Gradiente de color por segmento
            if (i > segments * 0.9) ctx.fillStyle = '#ff0000'; // Zona Roja (Clipping)
            else if (i > segments * 0.7) ctx.fillStyle = '#ffff00'; // Zona Amarilla (Warm)
            else ctx.fillStyle = '#00ff00'; // Zona Verde (Safe)
          } else {
            ctx.fillStyle = '#1a1a1a';
          }

          ctx.fillRect(segX, y + 1, segWidth - 1, 8);
        }

        // Marcador de pico (Línea flotante)
        const peakX = 38 + peakPos;
        ctx.fillStyle = peaksRef.current[peakKey] > 220 ? '#ff0000' : '#ffffff';
        ctx.fillRect(peakX - 1, y, 2, 10);

        // Glow sutil en el pico
        if (peaksRef.current[peakKey] > 0) {
            ctx.shadowBlur = 4;
            ctx.shadowColor = ctx.fillStyle as string;
            ctx.fillRect(peakX - 1, y, 2, 10);
            ctx.shadowBlur = 0;
        }
      };

      // Renderizar ambos canales
      drawMeter(12, leftVal, 'left', 'CH-L');
      drawMeter(28, rightVal, 'right', 'CH-R');

      // Scanlines y ruido digital estético
      ctx.fillStyle = 'rgba(255, 255, 255, 0.01)';
      for (let i = 0; i < height; i += 2) {
        ctx.fillRect(0, i, width, 1);
      }
    };

    draw();

    return () => {
      cancelAnimationFrame(animationId);
    };
  }, [analyser, isPaused]);

  return (
    <div className="w-full h-full flex items-center justify-center bg-black">
      <canvas 
        ref={canvasRef} 
        width={320} 
        height={50} 
        className="w-full h-full object-contain"
      />
    </div>
  );
};

