import React, { useEffect, useRef } from 'react';

interface VisualizerProps {
  analyser: AnalyserNode | null;
  color: string;
  isPaused: boolean;
}

const Visualizer: React.FC<VisualizerProps> = ({ analyser, isPaused }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const peaksRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });

  useEffect(() => {
    if (!canvasRef.current || !analyser) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    let animationId: number;

    const draw = () => {
      animationId = requestAnimationFrame(draw);
      analyser.getByteFrequencyData(dataArray);

      const width = canvas.width;
      const height = canvas.height;

      // Fondo ultra oscuro
      ctx.fillStyle = '#050505';
      ctx.fillRect(0, 0, width, height);

      // --- ANALIZADOR DE ESPECTRO SUTIL (FONDO) ---
      const barCount = 32;
      const barWidth = (width / barCount);

      ctx.globalAlpha = 0.12;
      for (let i = 0; i < barCount; i++) {
        const idx = Math.floor(i * (bufferLength / barCount));
        const val = isPaused ? 0 : dataArray[idx];
        const h = (val / 255) * (height * 0.7);
        ctx.fillStyle = '#008800';
        ctx.fillRect(i * barWidth, height - h - 5, barWidth - 1, h);
      }
      ctx.globalAlpha = 1.0;

      // --- AJUSTE DE CANALES L/R CORREGIDO ---
      // L (Izquierdo): Captura bajos y medios-bajos. 
      const leftSlice = dataArray.slice(1, 15);
      const leftVal = isPaused ? 0 : leftSlice.reduce((a, b) => Math.max(a, b), 0);

      // R (Derecho): Captura medios y agudos.
      // Se amplía el rango (3 a 40) para captar más energía y se aplica un boost de ganancia
      // para compensar la caída natural de amplitud en frecuencias altas en radio streams.
      const rightSlice = dataArray.slice(3, 40);
      const rightValRaw = isPaused ? 0 : rightSlice.reduce((a, b) => Math.max(a, b), 0);

      // Aplicamos un factor de corrección (+3dB aprox visualmente) para igualar al canal L.
      const rightVal = Math.min(255, rightValRaw * 1.45);

      const drawMeter = (y: number, value: number, peakKey: 'left' | 'right', label: string) => {
        const meterPadding = 45;
        const meterWidth = width - meterPadding;

        // Suavizado de la señal para evitar parpadeos bruscos
        const fillWidth = (value / 255) * meterWidth;

        // Caída de pico balística
        if (value > peaksRef.current[peakKey]) {
          peaksRef.current[peakKey] = value;
        } else {
          peaksRef.current[peakKey] -= 2.2; // Caída controlada
          if (peaksRef.current[peakKey] < 0) peaksRef.current[peakKey] = 0;
        }
        const peakPos = (peaksRef.current[peakKey] / 255) * meterWidth;

        // Etiqueta Canal
        ctx.fillStyle = '#999';
        ctx.font = 'bold 8px "Orbitron", sans-serif';
        ctx.fillText(label, 6, y + 8);

        // Fondo del carril
        ctx.fillStyle = '#0a0a0a';
        ctx.fillRect(38, y, meterWidth, 10);

        // Segmentos LED digitales
        const segments = 45;
        const segWidth = meterWidth / segments;

        for(let i = 0; i < segments; i++) {
          const segX = 38 + (i * segWidth);
          const isFull = (i / segments) * meterWidth < fillWidth;

          if (isFull) {
            if (i > segments * 0.88) ctx.fillStyle = '#ff0000'; // Pico / Clipping
            else if (i > segments * 0.65) ctx.fillStyle = '#ffff00'; // Saturación
            else ctx.fillStyle = '#00ff00'; // Normal
          } else {
            ctx.fillStyle = '#151515'; // Apagado
          }
          ctx.fillRect(segX, y + 1, segWidth - 1, 8);
        }

        // Marcador de pico flotante
        const peakX = 38 + peakPos;
        ctx.fillStyle = peaksRef.current[peakKey] > 225 ? '#ff0000' : '#ffffff';
        ctx.fillRect(peakX - 1, y, 2, 10);
      };

      // Render de los canales L y R con el balance corregido
      drawMeter(12, leftVal, 'left', 'CH-L');
      drawMeter(28, rightVal, 'right', 'CH-R');

      // Líneas de escaneo estéticas
      ctx.fillStyle = 'rgba(0, 255, 0, 0.015)';
      for (let i = 0; i < height; i += 3) {
        ctx.fillRect(0, i, width, 1);
      }
    };

    draw();

    return () => {
      cancelAnimationFrame(animationId);
    };
  }, [analyser, isPaused]);

  return (
    <div className="w-full h-full flex items-center justify-center bg-black">
      <canvas 
        ref={canvasRef} 
        width={320} 
        height={50} 
        className="w-full h-full object-contain"
      />
    </div>
  );
};

