import React, { useEffect, useRef } from 'react';

interface VisualizerProps {
  analyser: AnalyserNode | null;
  color: string;
  isPaused: boolean;
}

const Visualizer: React.FC<VisualizerProps> = ({ analyser, isPaused }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const peaksRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });
  const lastValuesRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });

  useEffect(() => {
    if (!canvasRef.current || !analyser) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    let animationId: number;

    const draw = () => {
      animationId = requestAnimationFrame(draw);
      analyser.getByteFrequencyData(dataArray);

      const width = canvas.width;
      const height = canvas.height;

      // Fondo negro técnico
      ctx.fillStyle = '#020202';
      ctx.fillRect(0, 0, width, height);

      // --- PROCESAMIENTO DE SEÑAL CALIBRADO ---
      // Canal L (Referencia 0dB visual)
      const leftRange = dataArray.slice(1, 10);
      const leftTarget = isPaused ? 0 : Math.max(...leftRange);

      // Canal R: Ajustado a -3dB respecto a L (~0.707 de factor de escala)
      // para corregir la percepción de volumen solicitada.
      const rightRange = dataArray.slice(1, 10); // Usamos mismo rango para balance real
      const rightTargetRaw = isPaused ? 0 : Math.max(...rightRange);
      const rightTarget = Math.min(255, rightTargetRaw * 0.707);

      // Suavizado (Attack/Release) para movimiento orgánico
      const smoothFactor = 0.25;
      lastValuesRef.current.left += (leftTarget - lastValuesRef.current.left) * smoothFactor;
      lastValuesRef.current.right += (rightTarget - lastValuesRef.current.right) * smoothFactor;

      const drawMeter = (y: number, value: number, peakKey: 'left' | 'right', label: string) => {
        const xStart = 40;
        const meterWidth = width - xStart - 10;

        // Caída de picos balística
        if (value > peaksRef.current[peakKey]) {
          peaksRef.current[peakKey] = value;
        } else {
          peaksRef.current[peakKey] -= 1.8;
          if (peaksRef.current[peakKey] < 0) peaksRef.current[peakKey] = 0;
        }

        // Etiqueta técnica
        ctx.fillStyle = '#666';
        ctx.font = '700 8px "Orbitron", sans-serif';
        ctx.fillText(label, 8, y + 8);

        // Carril de fondo
        ctx.fillStyle = '#080808';
        ctx.fillRect(xStart, y, meterWidth, 10);

        // Segmentos LED
        const numSegments = 60;
        const segWidth = meterWidth / numSegments;
        const activeSegments = (value / 255) * numSegments;
        const peakSegment = (peaksRef.current[peakKey] / 255) * numSegments;

        for (let i = 0; i < numSegments; i++) {
          const segX = xStart + (i * segWidth);
          const isActive = i <= activeSegments;
          const isPeak = Math.floor(peakSegment) === i;

          if (isActive) {
            if (i > numSegments * 0.92) ctx.fillStyle = '#ff0000';      // CLIP
            else if (i > numSegments * 0.85) ctx.fillStyle = '#ff8800'; // HOT
            else if (i > numSegments * 0.70) ctx.fillStyle = '#ffff00'; // WARM
            else if (i > numSegments * 0.40) ctx.fillStyle = '#aaff00'; // NORMAL
            else ctx.fillStyle = '#00ff00';                             // LOW
          } else if (isPeak) {
            ctx.fillStyle = i > numSegments * 0.9 ? '#ff0000' : '#ffffff';
          } else {
            ctx.fillStyle = '#111';
          }

          ctx.fillRect(segX, y + 1, segWidth - 1, 8);
        }

        // Marcadores de escala
        ctx.fillStyle = 'rgba(255,255,255,0.1)';
        const markings = [0.1, 0.4, 0.6, 0.75, 0.85, 0.95];
        markings.forEach(m => {
          ctx.fillRect(xStart + m * meterWidth, y - 2, 1, 14);
        });
      };

      drawMeter(12, lastValuesRef.current.left, 'left', 'CH-L');
      drawMeter(28, lastValuesRef.current.right, 'right', 'CH-R');

      // Overlay estético
      const gradient = ctx.createLinearGradient(0, 0, 0, height);
      gradient.addColorStop(0, 'rgba(0, 255, 0, 0.05)');
      gradient.addColorStop(0.5, 'transparent');
      gradient.addColorStop(1, 'rgba(0, 255, 0, 0.05)');
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, width, height);

      ctx.fillStyle = 'rgba(0, 0, 0, 0.2)';
      for (let i = 0; i < height; i += 2) {
        ctx.fillRect(0, i, width, 1);
      }
    };

    draw();

    return () => {
      cancelAnimationFrame(animationId);
    };
  }, [analyser, isPaused]);

  return (
    <div className="w-full h-full flex items-center justify-center bg-black rounded-sm overflow-hidden border border-gray-900">
      <canvas 
        ref={canvasRef} 
        width={320} 
        height={50} 
        className="w-full h-full object-contain"
      />
    </div>
  );
};

export default Visualizer;

