import React, { useEffect, useRef } from 'react';

interface VisualizerProps {
  analyser: AnalyserNode | null;
  color: string;
  isPaused: boolean;
}

const Visualizer: React.FC<VisualizerProps> = ({ analyser, isPaused }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const peaksRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });
  const lastValuesRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });

  useEffect(() => {
    if (!canvasRef.current || !analyser) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    let animationId: number;

    const draw = () => {
      animationId = requestAnimationFrame(draw);
      analyser.getByteFrequencyData(dataArray);

      const width = canvas.width;
      const height = canvas.height;

      // Fondo negro técnico con ligero brillo base
      ctx.fillStyle = '#050505';
      ctx.fillRect(0, 0, width, height);

      // --- PROCESAMIENTO DE SEÑAL CALIBRADO A 0dB (GANANCIA 1:1) ---
      // Seleccionamos un rango de bins que represente la energía total (RMS aproximado)
      // Bins 1 a 10 suelen tener la mayor energía en radio (bajos y fundamentales de voz)
      const sampleRange = dataArray.slice(1, 15);
      const rawSignal = isPaused ? 0 : Math.max(...sampleRange);

      // Calibración 0dB: No aplicamos multiplicadores reductores (como 0.707 o 0.98)
      // El valor 255 representa 0dBFS (Full Scale)
      const leftTarget = rawSignal;
      const rightTarget = rawSignal; // Simetría perfecta para 0dB de diferencia entre canales

      // Suavizado de Balística (Attack Pro / Release Suave)
      // Attack: 0.4 (rápido para transitorios)
      // Release: 0.15 (más lento para visibilidad)
      const attack = 0.4;
      const release = 0.15;

      const updateLevel = (current: number, target: number) => {
        const factor = target > current ? attack : release;
        return current + (target - current) * factor;
      };

      lastValuesRef.current.left = updateLevel(lastValuesRef.current.left, leftTarget);
      lastValuesRef.current.right = updateLevel(lastValuesRef.current.right, rightTarget);

      const drawMeter = (y: number, value: number, peakKey: 'left' | 'right', label: string) => {
        const xStart = 42;
        const meterWidth = width - xStart - 12;

        // Caída de picos balística "Sticky Peak"
        if (value > peaksRef.current[peakKey]) {
          peaksRef.current[peakKey] = value;
        } else {
          peaksRef.current[peakKey] -= 1.2; // Caída controlada de 1.2 unidades por frame
          if (peaksRef.current[peakKey] < 0) peaksRef.current[peakKey] = 0;
        }

        // Etiqueta de canal con estilo rack
        ctx.fillStyle = '#888';
        ctx.font = '700 9px "Orbitron", sans-serif';
        ctx.fillText(label, 6, y + 8);

        // Carril de fondo (LEDs apagados)
        ctx.fillStyle = '#111';
        ctx.fillRect(xStart, y, meterWidth, 10);

        // Renderizado de Segmentos LED
        const numSegments = 50;
        const segWidth = meterWidth / numSegments;
        const activeSegments = (value / 255) * numSegments;
        const peakSegment = (peaksRef.current[peakKey] / 255) * numSegments;

        for (let i = 0; i < numSegments; i++) {
          const segX = xStart + (i * segWidth);
          const isActive = i <= activeSegments;
          const isPeak = Math.floor(peakSegment) === i;

          if (isActive) {
            // Escala de color estándar de broadcast:
            if (i > numSegments * 0.90) ctx.fillStyle = '#ff0000';      // +3dB a 0dB (CLIP)
            else if (i > numSegments * 0.82) ctx.fillStyle = '#ffaa00'; // 0dB a -3dB (HOT)
            else if (i > numSegments * 0.70) ctx.fillStyle = '#ffff00'; // -3dB a -10dB (WARM)
            else if (i > numSegments * 0.45) ctx.fillStyle = '#00ff00'; // -10dB a -25dB (NORMAL)
            else ctx.fillStyle = '#008800';                             // < -25dB (LOW)
          } else if (isPeak) {
            // El segmento de pico se mantiene blanco o rojo si está en zona de clip
            ctx.fillStyle = i > numSegments * 0.85 ? '#ff0000' : '#ffffff';
          } else {
            ctx.fillStyle = '#181818'; // LED Inactivo
          }

          // Dibujar el LED con un pequeño espacio entre segmentos
          ctx.fillRect(segX, y + 1, segWidth - 1.5, 8);
        }

        // Marcas de escala técnica (-20, -10, -5, 0, +3)
        ctx.fillStyle = 'rgba(255,255,255,0.15)';
        const markings = [0.2, 0.5, 0.7, 0.85, 0.95];
        markings.forEach(m => {
          ctx.fillRect(xStart + m * meterWidth, y - 2, 1, 14);
        });
      };

      // Dibujar ambos canales con calibración 0dB
      drawMeter(12, lastValuesRef.current.left, 'left', 'L-0dB');
      drawMeter(28, lastValuesRef.current.right, 'right', 'R-0dB');

      // Efecto Scanline y cristal LCD
      ctx.fillStyle = 'rgba(0, 0, 0, 0.3)';
      for (let i = 0; i < height; i += 2) {
        ctx.fillRect(0, i, width, 1);
      }

      // Brillo en los bordes
      const gloss = ctx.createLinearGradient(0, 0, 0, height);
      gloss.addColorStop(0, 'rgba(255, 255, 255, 0.05)');
      gloss.addColorStop(0.5, 'transparent');
      gloss.addColorStop(1, 'rgba(0, 0, 0, 0.2)');
      ctx.fillStyle = gloss;
      ctx.fillRect(0, 0, width, height);
    };

    draw();

    return () => {
      cancelAnimationFrame(animationId);
    };
  }, [analyser, isPaused]);

  return (
    <div className="w-full h-full flex items-center justify-center bg-black rounded-sm overflow-hidden border border-gray-800 shadow-inner">
      <canvas 
        ref={canvasRef} 
        width={320} 
        height={50} 
        className="w-full h-full object-contain"
      />
    </div>
  );
};

export default Visualizer;

import React, { useEffect, useRef, forwardRef, useImperativeHandle } from 'react';
import { PlayerState } from '../types';

declare const Hls: any;

interface AudioEngineProps {
  url: string;
  volume: number;
  isMuted: boolean;
  onStateChange: (state: PlayerState) => void;
  onAnalyserCreated: (analyser: AnalyserNode) => void;
}

export interface AudioEngineHandle {
  play: () => void;
  pause: () => void;
  toggle: () => void;
}

const AudioEngine = forwardRef<AudioEngineHandle, AudioEngineProps>(({
  url,
  volume,
  isMuted,
  onStateChange,
  onAnalyserCreated
}, ref) => {
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const hlsRef = useRef<any>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);

  useImperativeHandle(ref, () => ({
    play: () => audioRef.current?.play(),
    pause: () => audioRef.current?.pause(),
    toggle: () => {
      if (audioRef.current?.paused) {
        audioRef.current.play();
      } else {
        audioRef.current?.pause();
      }
    }
  }));

  const setupWebAudio = () => {
    if (!audioRef.current) return;
    if (!audioContextRef.current) {
      const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
      audioContextRef.current = new AudioContextClass();

      // Aumentamos fftSize para mayor precisión en la detección de niveles
      analyserRef.current = audioContextRef.current.createAnalyser();
      analyserRef.current.fftSize = 256; 
      analyserRef.current.smoothingTimeConstant = 0.3; // Suavizado moderado para evitar jitter visual

      sourceRef.current = audioContextRef.current.createMediaElementSource(audioRef.current);
      sourceRef.current.connect(analyserRef.current);
      analyserRef.current.connect(audioContextRef.current.destination);

      onAnalyserCreated(analyserRef.current);
    }

    if (audioContextRef.current.state === 'suspended') {
      audioContextRef.current.resume();
    }
  };

  useEffect(() => {
    if (!audioRef.current) return;

    onStateChange(PlayerState.LOADING);

    // Limpieza previa
    if (hlsRef.current) {
      hlsRef.current.destroy();
      hlsRef.current = null;
    }
    audioRef.current.pause();
    audioRef.current.src = "";
    audioRef.current.load();

    const isHls = url.toLowerCase().includes('.m3u8');

    if (isHls && Hls.isSupported()) {
      const hls = new Hls();
      hlsRef.current = hls;
      hls.loadSource(url);
      hls.attachMedia(audioRef.current);
      hls.on(Hls.Events.MANIFEST_PARSED, () => {
        // Listo para sonar
      });
      hls.on(Hls.Events.ERROR, (_: any, data: any) => {
        if (data.fatal) {
           onStateChange(PlayerState.ERROR);
        }
      });
    } else {
      // Audio directo (MP3, AAC) o Safari HLS nativo
      audioRef.current.src = url;
    }

    return () => {
      if (hlsRef.current) {
        hlsRef.current.destroy();
      }
    };
  }, [url]);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = volume;
      audioRef.current.muted = isMuted;
    }
  }, [volume, isMuted]);

  return (
    <audio
      ref={audioRef}
      onPlay={() => {
        setupWebAudio();
        onStateChange(PlayerState.PLAYING);
      }}
      onPause={() => onStateChange(PlayerState.PAUSED)}
      onWaiting={() => onStateChange(PlayerState.LOADING)}
      onPlaying={() => onStateChange(PlayerState.PLAYING)}
      onEnded={() => onStateChange(PlayerState.IDLE)}
      onError={() => onStateChange(PlayerState.ERROR)}
      crossOrigin="anonymous"
    />
  );
});

