import React, { useEffect, useRef, forwardRef, useImperativeHandle } from 'react';
import { PlayerState, StereoAnalysers } from '../types';

declare const Hls: any;

interface AudioEngineProps {
  url: string;
  volume: number;
  isMuted: boolean;
  onStateChange: (state: PlayerState) => void;
  onAnalyserCreated: (analysers: StereoAnalysers) => void;
}

export interface AudioEngineHandle {
  play: () => void;
  pause: () => void;
  toggle: () => void;
}

const AudioEngine = forwardRef<AudioEngineHandle, AudioEngineProps>(({
  url,
  volume,
  isMuted,
  onStateChange,
  onAnalyserCreated
}, ref) => {
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const hlsRef = useRef<any>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);
  const splitterRef = useRef<ChannelSplitterNode | null>(null);
  const analyserLRef = useRef<AnalyserNode | null>(null);
  const analyserRRef = useRef<AnalyserNode | null>(null);

  useImperativeHandle(ref, () => ({
    play: () => audioRef.current?.play(),
    pause: () => audioRef.current?.pause(),
    toggle: () => {
      if (audioRef.current?.paused) {
        audioRef.current.play();
      } else {
        audioRef.current?.pause();
      }
    }
  }));

  const setupWebAudio = () => {
    if (!audioRef.current) return;

    if (!audioContextRef.current) {
      const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
      audioContextRef.current = new AudioContextClass();

      const ctx = audioContextRef.current;

      // Crear nodo fuente
      sourceRef.current = ctx.createMediaElementSource(audioRef.current);

      // Splitter para separar L y R (2 canales)
      splitterRef.current = ctx.createChannelSplitter(2);

      // Analizadores independientes para cada canal
      analyserLRef.current = ctx.createAnalyser();
      analyserRRef.current = ctx.createAnalyser();

      [analyserLRef.current, analyserRRef.current].forEach(a => {
        a.fftSize = 256;
        a.smoothingTimeConstant = 0.4;
      });

      // Conexiones: Source -> Splitter -> Analysers -> Destination
      sourceRef.current.connect(splitterRef.current);
      splitterRef.current.connect(analyserLRef.current, 0); // Canal 0 a Analizador L
      splitterRef.current.connect(analyserRRef.current, 1); // Canal 1 a Analizador R

      // Nota: MediaElementAudioSourceNode debe conectarse al destino para que se escuche
      sourceRef.current.connect(ctx.destination);

      onAnalyserCreated({
        left: analyserLRef.current,
        right: analyserRRef.current
      });
    }

    if (audioContextRef.current.state === 'suspended') {
      audioContextRef.current.resume();
    }
  };

  useEffect(() => {
    if (!audioRef.current) return;

    onStateChange(PlayerState.LOADING);

    if (hlsRef.current) {
      hlsRef.current.destroy();
      hlsRef.current = null;
    }

    audioRef.current.pause();
    audioRef.current.src = "";
    audioRef.current.load();

    const isHls = url.toLowerCase().includes('.m3u8');

    if (isHls && Hls.isSupported()) {
      const hls = new Hls({
        xhrSetup: (xhr: any) => {
          xhr.withCredentials = false;
        }
      });
      hlsRef.current = hls;
      hls.loadSource(url);
      hls.attachMedia(audioRef.current);
      hls.on(Hls.Events.ERROR, (_: any, data: any) => {
        if (data.fatal) {
           onStateChange(PlayerState.ERROR);
        }
      });
    } else {
      audioRef.current.src = url;
    }

    return () => {
      if (hlsRef.current) {
        hlsRef.current.destroy();
      }
    };
  }, [url]);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = volume;
      audioRef.current.muted = isMuted;
    }
  }, [volume, isMuted]);

  return (
    <audio
      ref={audioRef}
      onPlay={() => {
        setupWebAudio();
        onStateChange(PlayerState.PLAYING);
      }}
      onPause={() => onStateChange(PlayerState.PAUSED)}
      onWaiting={() => onStateChange(PlayerState.LOADING)}
      onPlaying={() => onStateChange(PlayerState.PLAYING)}
      onEnded={() => onStateChange(PlayerState.IDLE)}
      onError={() => onStateChange(PlayerState.ERROR)}
      crossOrigin="anonymous"
    />
  );
});

