import React, { useEffect, useRef } from 'react';
import { StereoAnalysers } from '../types';

interface VisualizerProps {
  analysers: StereoAnalysers | null;
  isPaused: boolean;
}

const Visualizer: React.FC<VisualizerProps> = ({ analysers, isPaused }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const peaksRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });
  const lastValuesRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });

  useEffect(() => {
    if (!canvasRef.current || !analysers) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const dataL = new Uint8Array(analysers.left.frequencyBinCount);
    const dataR = new Uint8Array(analysers.right.frequencyBinCount);
    let animationId: number;

    const draw = () => {
      animationId = requestAnimationFrame(draw);

      analysers.left.getByteFrequencyData(dataL);
      analysers.right.getByteFrequencyData(dataR);

      const width = canvas.width;
      const height = canvas.height;

      // Fondo negro técnico
      ctx.fillStyle = '#020202';
      ctx.fillRect(0, 0, width, height);

      // Calibración 0dB (Ganancia unitaria): 255 = 0dBFS
      // Tomamos el promedio de la banda de energía principal (bajos/medios)
      const getLevel = (data: Uint8Array) => {
        if (isPaused) return 0;
        // Rango de 20Hz a ~400Hz para captar la potencia real
        let sum = 0;
        const count = 12;
        for(let i = 1; i <= count; i++) {
          sum += data[i];
        }
        return sum / count;
      };

      const leftTarget = getLevel(dataL);
      const rightTarget = getLevel(dataR);

      // Balística profesional (Attack rápido / Release moderado)
      const attack = 0.5;
      const release = 0.2;

      const smooth = (curr: number, target: number) => {
        const factor = target > curr ? attack : release;
        return curr + (target - curr) * factor;
      };

      lastValuesRef.current.left = smooth(lastValuesRef.current.left, leftTarget);
      lastValuesRef.current.right = smooth(lastValuesRef.current.right, rightTarget);

      const drawMeter = (y: number, value: number, peakKey: 'left' | 'right', label: string) => {
        const xStart = 42;
        const meterWidth = width - xStart - 12;

        // Picos "Sticky"
        if (value > peaksRef.current[peakKey]) {
          peaksRef.current[peakKey] = value;
        } else {
          peaksRef.current[peakKey] -= 1.0; 
          if (peaksRef.current[peakKey] < 0) peaksRef.current[peakKey] = 0;
        }

        ctx.fillStyle = '#666';
        ctx.font = '800 8px "Orbitron", sans-serif';
        ctx.fillText(label, 6, y + 8);

        // LED Bar background
        ctx.fillStyle = '#111';
        ctx.fillRect(xStart, y, meterWidth, 10);

        const numSegments = 60;
        const segWidth = meterWidth / numSegments;
        const activeSegments = (value / 255) * numSegments;
        const peakSegment = (peaksRef.current[peakKey] / 255) * numSegments;

        for (let i = 0; i < numSegments; i++) {
          const segX = xStart + (i * segWidth);
          const isActive = i <= activeSegments;
          const isPeak = Math.floor(peakSegment) === i;

          if (isActive) {
            // Colores de broadcast (0dB es aprox el 85% de la escala digital en radio)
            if (i > numSegments * 0.92) ctx.fillStyle = '#ff0000'; // CLIP
            else if (i > numSegments * 0.82) ctx.fillStyle = '#ff8800'; // 0dB Ref
            else if (i > numSegments * 0.65) ctx.fillStyle = '#ffff00'; // Warm
            else if (i > numSegments * 0.35) ctx.fillStyle = '#00ff00'; // Normal
            else ctx.fillStyle = '#006600'; // Low
          } else if (isPeak) {
            ctx.fillStyle = i > numSegments * 0.9 ? '#ff0000' : '#ffffff';
          } else {
            ctx.fillStyle = '#181818';
          }

          ctx.fillRect(segX, y + 1, segWidth - 1, 8);
        }

        // Marcas de escala -30, -18, -12, -6, 0, +3
        ctx.fillStyle = 'rgba(255,255,255,0.1)';
        [0.2, 0.45, 0.65, 0.75, 0.82, 0.95].forEach(m => {
          ctx.fillRect(xStart + m * meterWidth, y - 2, 1, 14);
        });
      };

      drawMeter(12, lastValuesRef.current.left, 'left', 'CH-L');
      drawMeter(28, lastValuesRef.current.right, 'right', 'CH-R');

      // Scanlines y efecto cristal
      ctx.fillStyle = 'rgba(0,0,0,0.2)';
      for (let i = 0; i < height; i += 2) ctx.fillRect(0, i, width, 1);
    };

    draw();
    return () => cancelAnimationFrame(animationId);
  }, [analysers, isPaused]);

  return (
    <div className="w-full h-full bg-black border border-gray-800 rounded-sm overflow-hidden">
      <canvas ref={canvasRef} width={320} height={50} className="w-full h-full object-contain" />
    </div>
  );
};

export default Visualizer;

