export enum VisualizerType {
  LED_BAR = 'LED_BAR',
  SPECTRUM = 'SPECTRUM',
  ANALOG = 'ANALOG',
  OSCILLOSCOPE = 'OSCILLOSCOPE'
}

import React, { useEffect, useRef } from 'react';
import { StereoAnalysers, VisualizerType } from '../types';

interface VisualizerProps {
  analysers: StereoAnalysers | null;
  isPaused: boolean;
  type: VisualizerType;
}

const Visualizer: React.FC<VisualizerProps> = ({ analysers, isPaused, type }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const peaksRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });
  const lastValuesRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });
  const needleRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });

  useEffect(() => {
    if (!canvasRef.current || !analysers) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const dataL = new Uint8Array(analysers.left.frequencyBinCount);
    const dataR = new Uint8Array(analysers.right.frequencyBinCount);
    const timeL = new Uint8Array(analysers.left.fftSize);
    const timeR = new Uint8Array(analysers.right.fftSize);

    let animationId: number;

    const draw = () => {
      animationId = requestAnimationFrame(draw);

      analysers.left.getByteFrequencyData(dataL);
      analysers.right.getByteFrequencyData(dataR);
      analysers.left.getByteTimeDomainData(timeL);
      analysers.right.getByteTimeDomainData(timeR);

      const width = canvas.width;
      const height = canvas.height;

      // Technical black background
      ctx.fillStyle = '#020202';
      ctx.fillRect(0, 0, width, height);

      if (type === VisualizerType.LED_BAR) {
        drawLedBars(ctx, dataL, dataR, width, height);
      } else if (type === VisualizerType.SPECTRUM) {
        drawSpectrum(ctx, dataL, dataR, width, height);
      } else if (type === VisualizerType.ANALOG) {
        drawAnalogVU(ctx, dataL, dataR, width, height);
      } else if (type === VisualizerType.OSCILLOSCOPE) {
        drawOscilloscope(ctx, timeL, timeR, width, height);
      }

      // CRT/LCD Scanlines effect
      ctx.fillStyle = 'rgba(0,0,0,0.15)';
      for (let i = 0; i < height; i += 2) ctx.fillRect(0, i, width, 1);
    };

    const drawLedBars = (ctx: CanvasRenderingContext2D, dataL: Uint8Array, dataR: Uint8Array, width: number, height: number) => {
      const getLevel = (data: Uint8Array) => {
        if (isPaused) return 0;
        let sum = 0;
        const count = 12;
        for(let i = 1; i <= count; i++) sum += data[i];
        return sum / count;
      };

      const leftTarget = getLevel(dataL);
      const rightTarget = getLevel(dataR);
      const attack = 0.5, release = 0.2;
      const smooth = (curr: number, target: number) => {
        const factor = target > curr ? attack : release;
        return curr + (target - curr) * factor;
      };

      lastValuesRef.current.left = smooth(lastValuesRef.current.left, leftTarget);
      lastValuesRef.current.right = smooth(lastValuesRef.current.right, rightTarget);

      const drawSingleMeter = (y: number, value: number, peakKey: 'left' | 'right', label: string) => {
        const xStart = 42;
        const meterWidth = width - xStart - 12;
        if (value > peaksRef.current[peakKey]) peaksRef.current[peakKey] = value;
        else { peaksRef.current[peakKey] -= 1.0; if (peaksRef.current[peakKey] < 0) peaksRef.current[peakKey] = 0; }

        ctx.fillStyle = '#666';
        ctx.font = '800 8px "Orbitron", sans-serif';
        ctx.fillText(label, 6, y + 8);
        ctx.fillStyle = '#111';
        ctx.fillRect(xStart, y, meterWidth, 10);

        const numSegments = 60;
        const segWidth = meterWidth / numSegments;
        const activeSegments = (value / 255) * numSegments;
        const peakSegment = (peaksRef.current[peakKey] / 255) * numSegments;

        for (let i = 0; i < numSegments; i++) {
          const segX = xStart + (i * segWidth);
          if (i <= activeSegments) {
            if (i > numSegments * 0.92) ctx.fillStyle = '#ff0000';
            else if (i > numSegments * 0.82) ctx.fillStyle = '#ff8800';
            else if (i > numSegments * 0.65) ctx.fillStyle = '#ffff00';
            else if (i > numSegments * 0.35) ctx.fillStyle = '#00ff00';
            else ctx.fillStyle = '#006600';
          } else if (Math.floor(peakSegment) === i) {
            ctx.fillStyle = i > numSegments * 0.9 ? '#ff0000' : '#ffffff';
          } else ctx.fillStyle = '#181818';
          ctx.fillRect(segX, y + 1, segWidth - 1, 8);
        }
      };

      drawSingleMeter(12, lastValuesRef.current.left, 'left', 'CH-L');
      drawSingleMeter(28, lastValuesRef.current.right, 'right', 'CH-R');
    };

    const drawSpectrum = (ctx: CanvasRenderingContext2D, dataL: Uint8Array, dataR: Uint8Array, width: number, height: number) => {
      const barCount = 40;
      const barWidth = (width / barCount);
      const maxH = height - 10;

      for (let i = 0; i < barCount; i++) {
        // Average L and R for mono-ish display or split them? Let's mirror them
        const val = isPaused ? 0 : (dataL[i] + dataR[i]) / 2;
        const h = (val / 255) * maxH;

        const x = i * barWidth;
        const hue = (i / barCount) * 120 + 100; // Cyan to Green
        ctx.fillStyle = `hsl(${hue}, 100%, 50%)`;
        ctx.fillRect(x, height - h, barWidth - 1, h);

        // Glow effect
        ctx.shadowBlur = 5;
        ctx.shadowColor = `hsl(${hue}, 100%, 50%)`;
      }
      ctx.shadowBlur = 0;
    };

    const drawAnalogVU = (ctx: CanvasRenderingContext2D, dataL: Uint8Array, dataR: Uint8Array, width: number, height: number) => {
      const getLevel = (data: Uint8Array) => {
        if (isPaused) return 0;
        let sum = 0;
        for(let i = 1; i <= 8; i++) sum += data[i];
        return sum / 8;
      };

      const targetL = (getLevel(dataL) / 255);
      const targetR = (getLevel(dataR) / 255);

      // Heavier needle ballistics
      needleRef.current.left += (targetL - needleRef.current.left) * 0.15;
      needleRef.current.right += (targetR - needleRef.current.right) * 0.15;

      const drawNeedle = (centerX: number, centerY: number, level: number, label: string) => {
        const radius = height * 1.2;
        const angleRange = Math.PI / 3;
        const angle = -Math.PI / 2 - angleRange / 2 + (level * angleRange);

        // Scale
        ctx.strokeStyle = '#333';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(centerX, centerY, radius - 10, -Math.PI / 2 - angleRange / 2, -Math.PI / 2 + angleRange / 2);
        ctx.stroke();

        // Label
        ctx.fillStyle = '#00ff00';
        ctx.font = 'bold 8px Orbitron';
        ctx.fillText(label, centerX - 10, centerY - radius + 25);

        // Needle
        ctx.strokeStyle = '#ff0000';
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(centerX, centerY);
        const nx = centerX + Math.cos(angle) * (radius - 15);
        const ny = centerY + Math.sin(angle) * (radius - 15);
        ctx.lineTo(nx, ny);
        ctx.stroke();

        // Pin
        ctx.fillStyle = '#fff';
        ctx.beginPath();
        ctx.arc(centerX, centerY, 3, 0, Math.PI * 2);
        ctx.fill();
      };

      drawNeedle(width * 0.25, height + 10, needleRef.current.left, 'VU L');
      drawNeedle(width * 0.75, height + 10, needleRef.current.right, 'VU R');
    };

    const drawOscilloscope = (ctx: CanvasRenderingContext2D, timeL: Uint8Array, timeR: Uint8Array, width: number, height: number) => {
      ctx.strokeStyle = '#00ff00';
      ctx.lineWidth = 1.5;
      ctx.beginPath();

      const sliceWidth = width / timeL.length;
      let x = 0;

      for (let i = 0; i < timeL.length; i++) {
        const v = isPaused ? 128 : (timeL[i] + timeR[i]) / 2;
        const y = (v / 255) * height;

        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);

        x += sliceWidth;
      }

      ctx.lineTo(width, height / 2);
      ctx.stroke();

      // Trace line glow
      ctx.shadowBlur = 8;
      ctx.shadowColor = '#00ff00';
      ctx.stroke();
      ctx.shadowBlur = 0;
    };

    draw();
    return () => cancelAnimationFrame(animationId);
  }, [analysers, isPaused, type]);

  return (
    <div className="w-full h-full bg-black border border-gray-800 rounded-sm overflow-hidden cursor-pointer active:brightness-125 transition-all">
      <canvas ref={canvasRef} width={320} height={80} className="w-full h-full object-contain" />
    </div>
  );
};

export default Visualizer;

