import React, { useEffect, useRef } from 'react';
import { StereoAnalysers, VisualizerType } from '../types';

interface VisualizerProps {
  analysers: StereoAnalysers | null;
  isPaused: boolean;
  type: VisualizerType;
}

const Visualizer: React.FC<VisualizerProps> = ({ analysers, isPaused, type }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const peaksRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });
  const lastValuesRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });
  const needleRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });

  useEffect(() => {
    if (!canvasRef.current || !analysers) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const dataL = new Uint8Array(analysers.left.frequencyBinCount);
    const dataR = new Uint8Array(analysers.right.frequencyBinCount);
    const timeL = new Uint8Array(analysers.left.fftSize);
    const timeR = new Uint8Array(analysers.right.fftSize);

    let animationId: number;

    const draw = () => {
      animationId = requestAnimationFrame(draw);

      analysers.left.getByteFrequencyData(dataL);
      analysers.right.getByteFrequencyData(dataR);
      analysers.left.getByteTimeDomainData(timeL);
      analysers.right.getByteTimeDomainData(timeR);

      const width = canvas.width;
      const height = canvas.height;

      // Fondo oscuro técnico profundo
      ctx.fillStyle = '#020202';
      ctx.fillRect(0, 0, width, height);

      if (type === VisualizerType.LED_BAR) {
        drawLedBars(ctx, dataL, dataR, width, height);
      } else if (type === VisualizerType.SPECTRUM) {
        drawSpectrum(ctx, dataL, dataR, width, height);
      } else if (type === VisualizerType.ANALOG) {
        drawAnalogVU(ctx, dataL, dataR, width, height);
      } else if (type === VisualizerType.OSCILLOSCOPE) {
        drawOscilloscope(ctx, timeL, timeR, width, height);
      }

      // Efecto de cristal LCD / Scanlines
      ctx.fillStyle = 'rgba(0, 255, 0, 0.03)';
      for (let i = 0; i < height; i += 2) {
        ctx.fillRect(0, i, width, 1);
      }
    };

    const drawLedBars = (ctx: CanvasRenderingContext2D, dataL: Uint8Array, dataR: Uint8Array, width: number, height: number) => {
      const getLevel = (data: Uint8Array) => {
        if (isPaused) return 0;
        let sum = 0;
        const count = 16;
        for(let i = 1; i <= count; i++) sum += data[i];
        return sum / count;
      };

      const leftTarget = getLevel(dataL);
      const rightTarget = getLevel(dataR);
      const attack = 0.5, release = 0.15;

      const smooth = (curr: number, target: number) => {
        const factor = target > curr ? attack : release;
        return curr + (target - curr) * factor;
      };

      lastValuesRef.current.left = smooth(lastValuesRef.current.left, leftTarget);
      lastValuesRef.current.right = smooth(lastValuesRef.current.right, rightTarget);

      const barHeight = (height / 2) - 10;

      const drawSingleMeter = (y: number, value: number, peakKey: 'left' | 'right') => {
        const xStart = 5;
        const meterWidth = width - 10;
        if (value > peaksRef.current[peakKey]) peaksRef.current[peakKey] = value;
        else { peaksRef.current[peakKey] -= 0.6; if (peaksRef.current[peakKey] < 0) peaksRef.current[peakKey] = 0; }

        ctx.fillStyle = '#080808';
        ctx.fillRect(xStart, y, meterWidth, barHeight);

        const numSegments = 55;
        const segWidth = meterWidth / numSegments;
        const activeSegments = (value / 255) * numSegments;
        const peakSegment = (peaksRef.current[peakKey] / 255) * numSegments;

        for (let i = 0; i < numSegments; i++) {
          const segX = xStart + (i * segWidth);
          if (i <= activeSegments) {
            if (i > numSegments * 0.90) ctx.fillStyle = '#ff0000'; 
            else if (i > numSegments * 0.78) ctx.fillStyle = '#ffaa00'; 
            else if (i > numSegments * 0.60) ctx.fillStyle = '#ffff00'; 
            else ctx.fillStyle = '#00ff66'; 
          } else if (Math.floor(peakSegment) === i) {
            ctx.fillStyle = i > numSegments * 0.85 ? '#ff4444' : '#ffffff';
          } else {
            ctx.fillStyle = '#111111';
          }

          ctx.fillRect(segX, y + 1, segWidth - 1, barHeight - 2);
        }
      };

      drawSingleMeter(5, lastValuesRef.current.left, 'left');
      drawSingleMeter(height / 2 + 5, lastValuesRef.current.right, 'right');
    };

    const drawSpectrum = (ctx: CanvasRenderingContext2D, dataL: Uint8Array, dataR: Uint8Array, width: number, height: number) => {
      const barCount = 32;
      const barWidth = (width / barCount);
      const padding = 2;

      for (let i = 0; i < barCount; i++) {
        const val = isPaused ? 2 : (dataL[i] + dataR[i]) / 2;
        const h = (val / 255) * (height - 10);

        const x = i * barWidth;
        // Gradiente técnico
        const hue = (i / barCount) * 120 + 120; // De verde a azul
        ctx.fillStyle = `hsl(${hue}, 80%, 50%)`;
        ctx.fillRect(x + padding / 2, height - h - 2, barWidth - padding, h);

        // Línea de pico superior
        ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
        ctx.fillRect(x + padding / 2, height - h - 4, barWidth - padding, 1);
      }
    };

    const drawAnalogVU = (ctx: CanvasRenderingContext2D, dataL: Uint8Array, dataR: Uint8Array, width: number, height: number) => {
      const getLevel = (data: Uint8Array) => {
        if (isPaused) return 0;
        let sum = 0;
        for(let i = 1; i <= 6; i++) sum += data[i];
        return sum / 6;
      };

      const targetL = (getLevel(dataL) / 255);
      const targetR = (getLevel(dataR) / 255);

      needleRef.current.left += (targetL - needleRef.current.left) * 0.1;
      needleRef.current.right += (targetR - needleRef.current.right) * 0.1;

      const drawNeedle = (centerX: number, centerY: number, level: number) => {
        const radius = height * 1.2;
        const angleRange = Math.PI / 2.2;
        const startAngle = -Math.PI / 2 - angleRange / 2;
        const angle = startAngle + (level * angleRange);

        // Fondo de escala
        ctx.strokeStyle = '#1a1a1a';
        ctx.lineWidth = 4;
        ctx.beginPath();
        ctx.arc(centerX, centerY, radius - 10, startAngle, startAngle + angleRange);
        ctx.stroke();

        // Marcas
        ctx.strokeStyle = '#333';
        ctx.lineWidth = 1;
        for(let i = 0; i <= 8; i++) {
          const ma = startAngle + (i / 8) * angleRange;
          const r1 = radius - 10;
          const r2 = radius - (i % 4 === 0 ? 22 : 18);
          ctx.beginPath();
          ctx.moveTo(centerX + Math.cos(ma) * r1, centerY + Math.sin(ma) * r1);
          ctx.lineTo(centerX + Math.cos(ma) * r2, centerY + Math.sin(ma) * r2);
          ctx.stroke();
        }

        // Aguja
        ctx.strokeStyle = '#ff1122';
        ctx.lineWidth = 2;
        ctx.shadowBlur = 4;
        ctx.shadowColor = 'rgba(255,0,0,0.5)';
        ctx.beginPath();
        ctx.moveTo(centerX, centerY);
        ctx.lineTo(centerX + Math.cos(angle) * (radius - 5), centerY + Math.sin(angle) * (radius - 5));
        ctx.stroke();
        ctx.shadowBlur = 0;

        // Eje
        ctx.fillStyle = '#222';
        ctx.beginPath(); ctx.arc(centerX, centerY, 6, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#888';
        ctx.beginPath(); ctx.arc(centerX, centerY, 2, 0, Math.PI * 2); ctx.fill();
      };

      drawNeedle(width * 0.28, height + 5, needleRef.current.left);
      drawNeedle(width * 0.72, height + 5, needleRef.current.right);
    };

    const drawOscilloscope = (ctx: CanvasRenderingContext2D, timeL: Uint8Array, timeR: Uint8Array, width: number, height: number) => {
      ctx.strokeStyle = '#00ff44';
      ctx.lineWidth = 2;
      ctx.shadowBlur = 6;
      ctx.shadowColor = 'rgba(0, 255, 68, 0.5)';
      ctx.beginPath();

      const sliceWidth = width / timeL.length;
      let x = 0;

      for (let i = 0; i < timeL.length; i++) {
        const v = isPaused ? 128 : (timeL[i] + timeR[i]) / 2;
        const y = (v / 255) * height;

        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);

        x += sliceWidth;
      }
      ctx.stroke();
      ctx.shadowBlur = 0;
    };

    draw();
    return () => cancelAnimationFrame(animationId);
  }, [analysers, isPaused, type]);

  return (
    <div className="w-full h-full bg-[#050505] rounded-sm overflow-hidden border border-gray-900 flex items-center justify-center">
      <canvas ref={canvasRef} width={400} height={100} className="w-full h-full object-fill" />
    </div>
  );
};

export default Visualizer;

