import React, { useEffect, useRef } from 'react';
import { StereoAnalysers, VisualizerType } from '../types';

interface VisualizerProps {
  analysers: StereoAnalysers | null;
  isPaused: boolean;
  type: VisualizerType;
}

const Visualizer: React.FC<VisualizerProps> = ({ analysers, isPaused, type }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const peaksRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });
  const lastValuesRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });
  const needleRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });

  useEffect(() => {
    if (!canvasRef.current || !analysers) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    // Handle high DPI screens for sharp visuals
    const dpr = window.devicePixelRatio || 1;
    const resizeCanvas = () => {
      const parent = canvas.parentElement;
      if (!parent) return;
      const rect = parent.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.scale(dpr, dpr);
    };

    const resizeObserver = new ResizeObserver(resizeCanvas);
    resizeObserver.observe(canvas.parentElement!);
    resizeCanvas();

    const dataL = new Uint8Array(analysers.left.frequencyBinCount);
    const dataR = new Uint8Array(analysers.right.frequencyBinCount);
    const timeL = new Uint8Array(analysers.left.fftSize);
    const timeR = new Uint8Array(analysers.right.fftSize);

    let animationId: number;

    const draw = () => {
      animationId = requestAnimationFrame(draw);

      analysers.left.getByteFrequencyData(dataL);
      analysers.right.getByteFrequencyData(dataR);
      analysers.left.getByteTimeDomainData(timeL);
      analysers.right.getByteTimeDomainData(timeR);

      const width = canvas.width / dpr;
      const height = canvas.height / dpr;

      // Dark background
      ctx.fillStyle = '#050505';
      ctx.fillRect(0, 0, width, height);

      if (type === VisualizerType.LED_BAR) {
        drawLedBars(ctx, dataL, dataR, width, height);
      } else if (type === VisualizerType.SPECTRUM) {
        drawSpectrum(ctx, dataL, dataR, width, height);
      } else if (type === VisualizerType.ANALOG) {
        drawAnalogVU(ctx, dataL, dataR, width, height);
      } else if (type === VisualizerType.OSCILLOSCOPE) {
        drawOscilloscope(ctx, timeL, timeR, width, height);
      }

      // Pro CRT/LCD Overlay
      ctx.fillStyle = 'rgba(0, 255, 0, 0.02)';
      for (let i = 0; i < height; i += 2) {
        ctx.fillRect(0, i, width, 1);
      }
    };

    const drawLedBars = (ctx: CanvasRenderingContext2D, dataL: Uint8Array, dataR: Uint8Array, width: number, height: number) => {
      const getLevel = (data: Uint8Array) => {
        if (isPaused) return 0;
        // Focus on energy bands (lows and mids)
        let sum = 0;
        const start = 1;
        const count = 16;
        for(let i = start; i < start + count; i++) sum += data[i];
        return sum / count;
      };

      const leftTarget = getLevel(dataL);
      const rightTarget = getLevel(dataR);

      // Fine-tuned ballistics for "snappy" meters
      const attack = 0.6; 
      const release = 0.12;

      const smooth = (curr: number, target: number) => {
        const factor = target > curr ? attack : release;
        return curr + (target - curr) * factor;
      };

      lastValuesRef.current.left = smooth(lastValuesRef.current.left, leftTarget);
      lastValuesRef.current.right = smooth(lastValuesRef.current.right, rightTarget);

      const barPadding = 4;
      const barHeight = (height / 2) - barPadding;

      const drawSingleMeter = (y: number, value: number, peakKey: 'left' | 'right') => {
        const xStart = 4;
        const meterWidth = width - 8;

        // Dynamic peak decay
        if (value > peaksRef.current[peakKey]) {
          peaksRef.current[peakKey] = value;
        } else {
          peaksRef.current[peakKey] -= 1.5; 
          if (peaksRef.current[peakKey] < 0) peaksRef.current[peakKey] = 0;
        }

        ctx.fillStyle = '#111';
        ctx.fillRect(xStart, y, meterWidth, barHeight);

        const numSegments = 50;
        const segWidth = meterWidth / numSegments;
        const activeSegments = (value / 255) * numSegments;
        const peakSegment = (peaksRef.current[peakKey] / 255) * numSegments;

        for (let i = 0; i < numSegments; i++) {
          const segX = xStart + (i * segWidth);
          if (i <= activeSegments) {
            if (i > numSegments * 0.90) ctx.fillStyle = '#ff0000'; 
            else if (i > numSegments * 0.80) ctx.fillStyle = '#ffaa00'; 
            else if (i > numSegments * 0.65) ctx.fillStyle = '#ffff00'; 
            else ctx.fillStyle = '#00ff77'; 
          } else if (Math.floor(peakSegment) === i) {
            ctx.fillStyle = i > numSegments * 0.85 ? '#ff4444' : '#ffffff';
          } else {
            ctx.fillStyle = '#1a1a1a';
          }
          ctx.fillRect(segX, y + 1, segWidth - 1, barHeight - 2);
        }
      };

      drawSingleMeter(barPadding / 2, lastValuesRef.current.left, 'left');
      drawSingleMeter(height / 2 + barPadding / 2, lastValuesRef.current.right, 'right');
    };

    const drawSpectrum = (ctx: CanvasRenderingContext2D, dataL: Uint8Array, dataR: Uint8Array, width: number, height: number) => {
      const barCount = 32;
      const barWidth = width / barCount;
      const gap = 2;

      for (let i = 0; i < barCount; i++) {
        const val = isPaused ? 2 : (dataL[i] + dataR[i]) / 2;
        const h = (val / 255) * (height - 10);
        const x = i * barWidth;

        const hue = (i / barCount) * 160 + 80; 
        ctx.fillStyle = `hsl(${hue}, 80%, 50%)`;
        ctx.fillRect(x + gap / 2, height - h - 5, barWidth - gap, h);

        // Floating peak
        ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
        ctx.fillRect(x + gap / 2, height - h - 8, barWidth - gap, 2);
      }
    };

    const drawAnalogVU = (ctx: CanvasRenderingContext2D, dataL: Uint8Array, dataR: Uint8Array, width: number, height: number) => {
      const getLevel = (data: Uint8Array) => {
        if (isPaused) return 0;
        let sum = 0;
        const samples = 12;
        for(let i = 1; i <= samples; i++) sum += data[i];
        return sum / samples;
      };

      const targetL = getLevel(dataL) / 255;
      const targetR = getLevel(dataR) / 255;

      // Heavy needle physics
      needleRef.current.left += (targetL - needleRef.current.left) * 0.15;
      needleRef.current.right += (targetR - needleRef.current.right) * 0.15;

      const drawNeedle = (centerX: number, centerY: number, level: number) => {
        const radius = height * 1.3;
        const angleRange = Math.PI / 2.5;
        const startAngle = -Math.PI / 2 - angleRange / 2;
        const angle = startAngle + (level * angleRange);

        // Backdrop scale
        ctx.strokeStyle = '#222';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(centerX, centerY, radius - 15, startAngle, startAngle + angleRange);
        ctx.stroke();

        // Markings
        ctx.strokeStyle = '#444';
        ctx.lineWidth = 1;
        for(let i = 0; i <= 10; i++) {
          const ma = startAngle + (i / 10) * angleRange;
          const r1 = radius - 15;
          const r2 = radius - (i % 5 === 0 ? 28 : 22);
          ctx.beginPath();
          ctx.moveTo(centerX + Math.cos(ma) * r1, centerY + Math.sin(ma) * r1);
          ctx.lineTo(centerX + Math.cos(ma) * r2, centerY + Math.sin(ma) * r2);
          ctx.stroke();
        }

        // Needle
        ctx.strokeStyle = '#ff3344';
        ctx.lineWidth = 2.5;
        ctx.beginPath();
        ctx.moveTo(centerX, centerY);
        ctx.lineTo(centerX + Math.cos(angle) * (radius - 10), centerY + Math.sin(angle) * (radius - 10));
        ctx.stroke();

        // Center hub
        ctx.fillStyle = '#333';
        ctx.beginPath(); ctx.arc(centerX, centerY, 8, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#666';
        ctx.beginPath(); ctx.arc(centerX, centerY, 3, 0, Math.PI * 2); ctx.fill();
      };

      drawNeedle(width * 0.3, height + 10, needleRef.current.left);
      drawNeedle(width * 0.7, height + 10, needleRef.current.right);
    };

    const drawOscilloscope = (ctx: CanvasRenderingContext2D, timeL: Uint8Array, timeR: Uint8Array, width: number, height: number) => {
      ctx.strokeStyle = '#00ff66';
      ctx.lineWidth = 2.5;
      ctx.shadowBlur = 4;
      ctx.shadowColor = 'rgba(0, 255, 102, 0.4)';
      ctx.beginPath();

      const sliceWidth = width / timeL.length;
      let x = 0;

      for (let i = 0; i < timeL.length; i++) {
        const v = isPaused ? 128 : (timeL[i] + timeR[i]) / 2;
        const y = (v / 255) * height;

        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);

        x += sliceWidth;
      }
      ctx.stroke();
      ctx.shadowBlur = 0;
    };

    draw();
    return () => {
      cancelAnimationFrame(animationId);
      resizeObserver.disconnect();
    };
  }, [analysers, isPaused, type]);

  return (
    <div className="w-full h-full bg-[#030303] rounded-sm overflow-hidden border border-gray-900 shadow-inner relative">
      <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />
    </div>
  );
};

export default Visualizer;

import React, { useState, useRef, useCallback, useEffect } from 'react';
import { PlayerState, RadioStation, StereoAnalysers, VisualizerType } from './types';
import { STATIONS } from './constants';
import AudioEngine, { AudioEngineHandle } from './components/AudioEngine';
import Visualizer from './components/Visualizer';

const App: React.FC = () => {
  const [currentStation, setCurrentStation] = useState<RadioStation>(STATIONS[0]);
  const [selectedUrl, setSelectedUrl] = useState<string>(STATIONS[0].url);
  const [playerState, setPlayerState] = useState<PlayerState>(PlayerState.IDLE);
  const [volume, setVolume] = useState(0.8);
  const [analysers, setAnalysers] = useState<StereoAnalysers | null>(null);
  const [visType, setVisType] = useState<VisualizerType>(VisualizerType.LED_BAR);

  const audioEngineRef = useRef<AudioEngineHandle>(null);

  const handleStationClick = (station: RadioStation) => {
    setCurrentStation(station);
    const defaultUrl = station.qualities && station.qualities.length > 0 
      ? station.qualities[0].url 
      : station.url;

    setSelectedUrl(defaultUrl);
    setTimeout(() => {
      audioEngineRef.current?.play();
    }, 50);
  };

  const handleQualityChange = (url: string) => {
    if (url === selectedUrl) return;
    setSelectedUrl(url);
    setTimeout(() => {
      audioEngineRef.current?.play();
    }, 50);
  };

  const cycleVisualizer = () => {
    const types = Object.values(VisualizerType);
    const currentIndex = types.indexOf(visType);
    const nextIndex = (currentIndex + 1) % types.length;
    setVisType(types[nextIndex]);
  };

  const handleTogglePlay = useCallback(() => {
    audioEngineRef.current?.toggle();
  }, []);

  const isPlaying = playerState === PlayerState.PLAYING;
  const isLoading = playerState === PlayerState.LOADING;

  const currentQuality = currentStation.qualities?.find(q => q.url === selectedUrl);
  const currentBitrate = currentQuality?.bitrate || currentStation.bitrate || '128kbps';

  return (
    <div className="flex flex-col h-[100dvh] w-full bg-[#111] overflow-hidden select-none">
