              <button onClick={() => audioEngineRef.current?.pause()} className="winamp-btn px-6 py-3 text-xs border-gray-500">STOP</button>
           </div>
           <div className="flex flex-col items-end leading-none">
              <span className="text-[8px] text-gray-500 font-bold uppercase tracking-tighter">System Output</span>
              <div className="text-[11px] text-[#00ff00] font-bold tracking-widest font-mono">HI-RES AUDIO</div>
           </div>
        </div>
      </div>

      <AudioEngine
        ref={audioEngineRef}
        url={selectedUrl}
        volume={volume}
        isMuted={false}
        onStateChange={setPlayerState}
        onAnalyserCreated={setAnalysers}
      />

      <style>{`
        @keyframes marquee { 0% { transform: translateX(100%); } 100% { transform: translateX(-200%); } }
        @keyframes bounce { 0%, 100% { height: 4px; } 50% { height: 14px; } }
        input[type=range]::-webkit-slider-runnable-track { cursor: pointer; }
        select { -webkit-appearance: none; -moz-appearance: none; appearance: none; }
      `}</style>
    </div>
  );
};

