import React, { useEffect, useRef, forwardRef, useImperativeHandle } from 'react';
import { PlayerState, StereoAnalysers } from '../types';

declare const Hls: any;

interface AudioEngineProps {
  url: string;
  volume: number;
  isMuted: boolean;
  onStateChange: (state: PlayerState) => void;
  onAnalyserCreated: (analysers: StereoAnalysers) => void;
}

export interface AudioEngineHandle {
  play: () => void;
  pause: () => void;
  toggle: () => void;
}

const AudioEngine = forwardRef<AudioEngineHandle, AudioEngineProps>(({
  url,
  volume,
  isMuted,
  onStateChange,
  onAnalyserCreated
}, ref) => {
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const hlsRef = useRef<any>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);
  const analyserLRef = useRef<AnalyserNode | null>(null);
  const analyserRRef = useRef<AnalyserNode | null>(null);

  useImperativeHandle(ref, () => ({
    play: async () => {
      if (audioContextRef.current?.state === 'suspended') {
        await audioContextRef.current.resume();
      }
      audioRef.current?.play();
    },
    pause: () => audioRef.current?.pause(),
    toggle: async () => {
      if (audioContextRef.current?.state === 'suspended') {
        await audioContextRef.current.resume();
      }
      if (audioRef.current?.paused) {
        audioRef.current.play();
      } else {
        audioRef.current?.pause();
      }
    }
  }));

  const setupWebAudio = () => {
    if (!audioRef.current) return;

    if (!audioContextRef.current) {
      const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
      const ctx = new AudioContextClass();
      audioContextRef.current = ctx;

      sourceRef.current = ctx.createMediaElementSource(audioRef.current);

      const splitter = ctx.createChannelSplitter(2);

      // Creamos analizadores con settings optimizados para Radio
      const createOptimizedAnalyser = () => {
        const a = ctx.createAnalyser();
        a.fftSize = 512;
        a.smoothingTimeConstant = 0.7; // Suavidad profesional
        a.minDecibels = -85; // Más sensible al ruido bajo
        a.maxDecibels = -10; // Tope para que no clipée visualmente todo el tiempo
        return a;
      };

      analyserLRef.current = createOptimizedAnalyser();
      analyserRRef.current = createOptimizedAnalyser();

      // Añadimos ganancia interna para que el vúmetro se mueva bien incluso a volumen bajo
      const visualizerGain = ctx.createGain();
      visualizerGain.gain.value = 1.4; 

      sourceRef.current.connect(splitter);

      // Conectar canales a través de la ganancia de visualización
      splitter.connect(visualizerGain, 0); 
      // Si es mono, el canal 1 no existe, pero splitter intentará enviarlo
      splitter.connect(visualizerGain, 1).catch(() => {
        // Fallback si falla la conexión del segundo canal (mono)
        splitter.connect(visualizerGain, 0);
      });

      // Dividir de nuevo tras la ganancia para los analizadores L/R
      const analyzerSplitter = ctx.createChannelSplitter(2);
      visualizerGain.connect(analyzerSplitter);

      analyzerSplitter.connect(analyserLRef.current, 0);
      analyzerSplitter.connect(analyserRRef.current, 1).catch(() => {
         // Fallback mono: enviar canal 0 al analizador R también
         analyzerSplitter.connect(analyserLRef.current, 0);
      });

      // Importante: Conectar fuente a salida real (audio del móvil)
      sourceRef.current.connect(ctx.destination);

      onAnalyserCreated({
        left: analyserLRef.current,
        right: analyserRRef.current
      });
    }
  };

  useEffect(() => {
    if (!audioRef.current) return;
    onStateChange(PlayerState.LOADING);

    if (hlsRef.current) {
      hlsRef.current.destroy();
      hlsRef.current = null;
    }

    audioRef.current.pause();
    audioRef.current.src = "";
    audioRef.current.load();

    const isHls = url.toLowerCase().includes('.m3u8');

    if (isHls && Hls.isSupported()) {
      const hls = new Hls();
      hlsRef.current = hls;
      hls.loadSource(url);
      hls.attachMedia(audioRef.current);
      hls.on(Hls.Events.ERROR, (_: any, data: any) => {
        if (data.fatal) onStateChange(PlayerState.ERROR);
      });
    } else {
      audioRef.current.src = url;
    }
  }, [url]);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = volume;
      audioRef.current.muted = isMuted;
    }
  }, [volume, isMuted]);

  return (
    <audio
      ref={audioRef}
      onPlay={() => {
        setupWebAudio();
        onStateChange(PlayerState.PLAYING);
      }}
      onPause={() => onStateChange(PlayerState.PAUSED)}
      onWaiting={() => onStateChange(PlayerState.LOADING)}
      onPlaying={() => onStateChange(PlayerState.PLAYING)}
      onEnded={() => onStateChange(PlayerState.IDLE)}
      onError={() => onStateChange(PlayerState.ERROR)}
      crossOrigin="anonymous"
    />
  );
});

AudioEngine.displayName = 'AudioEngine';
export default AudioEngine;

import React, { useEffect, useRef } from 'react';
import { StereoAnalysers, VisualizerType } from '../types';

interface VisualizerProps {
  analysers: StereoAnalysers | null;
  isPaused: boolean;
  type: VisualizerType;
}

const Visualizer: React.FC<VisualizerProps> = ({ analysers, isPaused, type }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const peaksRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });
  const lastValuesRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });
  const needleRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });

  useEffect(() => {
    if (!canvasRef.current || !analysers) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    const resizeCanvas = () => {
      const parent = canvas.parentElement;
      if (!parent) return;
      const rect = parent.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.scale(dpr, dpr);
    };

    const resizeObserver = new ResizeObserver(resizeCanvas);
    resizeObserver.observe(canvas.parentElement!);
    resizeCanvas();

    const dataL = new Uint8Array(analysers.left.frequencyBinCount);
    const dataR = new Uint8Array(analysers.right.frequencyBinCount);
    const timeL = new Uint8Array(analysers.left.fftSize);
    const timeR = new Uint8Array(analysers.right.fftSize);

    let animationId: number;

    const draw = () => {
      animationId = requestAnimationFrame(draw);

      analysers.left.getByteFrequencyData(dataL);
      analysers.right.getByteFrequencyData(dataR);
      analysers.left.getByteTimeDomainData(timeL);
      analysers.right.getByteTimeDomainData(timeR);

      const width = canvas.width / dpr;
      const height = canvas.height / dpr;

      ctx.fillStyle = '#020202';
      ctx.fillRect(0, 0, width, height);

      // Si detectamos que el canal derecho está totalmente mudo (común en radio mono)
      // promediamos con el izquierdo para que ambos vúmetros se muevan
      const isRightSilent = !isPaused && dataR.every(v => v === 0);
      const effectiveDataR = isRightSilent ? dataL : dataR;
      const effectiveTimeR = isRightSilent ? timeL : timeR;

      if (type === VisualizerType.LED_BAR) {
        drawLedBars(ctx, dataL, effectiveDataR, width, height);
      } else if (type === VisualizerType.SPECTRUM) {
        drawSpectrum(ctx, dataL, effectiveDataR, width, height);
      } else if (type === VisualizerType.ANALOG) {
        drawAnalogVU(ctx, dataL, effectiveDataR, width, height);
      } else if (type === VisualizerType.OSCILLOSCOPE) {
        drawOscilloscope(ctx, timeL, effectiveTimeR, width, height);
      }

      ctx.fillStyle = 'rgba(0, 255, 0, 0.02)';
      for (let i = 0; i < height; i += 2) ctx.fillRect(0, i, width, 1);
    };

    const drawLedBars = (ctx: CanvasRenderingContext2D, dataL: Uint8Array, dataR: Uint8Array, width: number, height: number) => {
      const getLevel = (data: Uint8Array) => {
        if (isPaused) return 0;
        let sum = 0;
        const start = 1;
        const count = 10; // Enfocarnos en graves/medios para más movimiento
        for(let i = start; i < start + count; i++) sum += data[i];
        return (sum / count) * 1.1; // Pequeño boost extra
      };

      const leftTarget = Math.min(255, getLevel(dataL));
      const rightTarget = Math.min(255, getLevel(dataR));

      const attack = 0.55; 
      const release = 0.15;
      const smooth = (curr: number, target: number) => {
        const factor = target > curr ? attack : release;
        return curr + (target - curr) * factor;
      };

      lastValuesRef.current.left = smooth(lastValuesRef.current.left, leftTarget);
      lastValuesRef.current.right = smooth(lastValuesRef.current.right, rightTarget);

      const barPadding = 4;
      const barHeight = (height / 2) - barPadding;

      const drawSingleMeter = (y: number, value: number, peakKey: 'left' | 'right') => {
        const xStart = 4;
        const meterWidth = width - 8;

        if (value > peaksRef.current[peakKey]) {
          peaksRef.current[peakKey] = value;
        } else {
          peaksRef.current[peakKey] -= 1.2; 
          if (peaksRef.current[peakKey] < 0) peaksRef.current[peakKey] = 0;
        }

        ctx.fillStyle = '#0a0a0a';
        ctx.fillRect(xStart, y, meterWidth, barHeight);

        const numSegments = 40;
        const segWidth = meterWidth / numSegments;
        const activeSegments = (value / 255) * numSegments;
        const peakSegment = (peaksRef.current[peakKey] / 255) * numSegments;

        for (let i = 0; i < numSegments; i++) {
          const segX = xStart + (i * segWidth);
          if (i <= activeSegments) {
            if (i > numSegments * 0.90) ctx.fillStyle = '#ff0000'; 
            else if (i > numSegments * 0.78) ctx.fillStyle = '#ffaa00'; 
            else if (i > numSegments * 0.60) ctx.fillStyle = '#eeee00'; 
            else ctx.fillStyle = '#00ff44'; 
          } else if (Math.floor(peakSegment) === i && i > 0) {
            ctx.fillStyle = i > numSegments * 0.85 ? '#ff5555' : '#ffffff';
          } else {
            ctx.fillStyle = '#151515';
          }
          ctx.fillRect(segX, y + 1, segWidth - 1.5, barHeight - 2);
        }
      };

      drawSingleMeter(barPadding / 2, lastValuesRef.current.left, 'left');
      drawSingleMeter(height / 2 + barPadding / 2, lastValuesRef.current.right, 'right');
    };

    const drawSpectrum = (ctx: CanvasRenderingContext2D, dataL: Uint8Array, dataR: Uint8Array, width: number, height: number) => {
      const barCount = 30;
      const barWidth = width / barCount;
      const gap = 2;

      for (let i = 0; i < barCount; i++) {
        const val = isPaused ? 2 : (dataL[i] + dataR[i]) / 2;
        const h = (val / 255) * (height - 10);
        const x = i * barWidth;

        const hue = (i / barCount) * 140 + 100; 
        ctx.fillStyle = `hsl(${hue}, 85%, 50%)`;
        ctx.fillRect(x + gap / 2, height - h - 4, barWidth - gap, h);

        ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
        ctx.fillRect(x + gap / 2, height - h - 6, barWidth - gap, 1.5);
      }
    };

    const drawAnalogVU = (ctx: CanvasRenderingContext2D, dataL: Uint8Array, dataR: Uint8Array, width: number, height: number) => {
      const getLevel = (data: Uint8Array) => {
        if (isPaused) return 0;
        let sum = 0;
        const samples = 8;
        for(let i = 1; i <= samples; i++) sum += data[i];
        return (sum / samples) / 255;
      };

      needleRef.current.left += (getLevel(dataL) - needleRef.current.left) * 0.15;
      needleRef.current.right += (getLevel(dataR) - needleRef.current.right) * 0.15;

      const drawNeedle = (centerX: number, centerY: number, level: number) => {
        const radius = height * 1.35;
        const angleRange = Math.PI / 2.5;
        const startAngle = -Math.PI / 2 - angleRange / 2;
        const angle = startAngle + (level * angleRange);

        ctx.strokeStyle = '#1a1a1a';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(centerX, centerY, radius - 15, startAngle, startAngle + angleRange);
        ctx.stroke();

        ctx.strokeStyle = '#444';
        ctx.lineWidth = 1;
        for(let i = 0; i <= 6; i++) {
          const ma = startAngle + (i / 6) * angleRange;
          ctx.beginPath();
          ctx.moveTo(centerX + Math.cos(ma) * (radius - 15), centerY + Math.sin(ma) * (radius - 15));
          ctx.lineTo(centerX + Math.cos(ma) * (radius - 25), centerY + Math.sin(ma) * (radius - 25));
          ctx.stroke();
        }

        ctx.strokeStyle = '#ff2233';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(centerX, centerY);
        ctx.lineTo(centerX + Math.cos(angle) * (radius - 12), centerY + Math.sin(angle) * (radius - 12));
        ctx.stroke();

        ctx.fillStyle = '#222';
        ctx.beginPath(); ctx.arc(centerX, centerY, 7, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#666';
        ctx.beginPath(); ctx.arc(centerX, centerY, 2.5, 0, Math.PI * 2); ctx.fill();
      };

      drawNeedle(width * 0.3, height + 8, needleRef.current.left);
      drawNeedle(width * 0.7, height + 8, needleRef.current.right);
    };

    const drawOscilloscope = (ctx: CanvasRenderingContext2D, timeL: Uint8Array, timeR: Uint8Array, width: number, height: number) => {
      ctx.strokeStyle = '#00ff55';
      ctx.lineWidth = 2.5;
      ctx.beginPath();

      const sliceWidth = width / timeL.length;
      let x = 0;
      for (let i = 0; i < timeL.length; i++) {
        const v = isPaused ? 128 : (timeL[i] + timeR[i]) / 2;
        const y = (v / 255) * height;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
        x += sliceWidth;
      }
      ctx.stroke();
    };

    draw();
    return () => {
      cancelAnimationFrame(animationId);
      resizeObserver.disconnect();
    };
  }, [analysers, isPaused, type]);

  return (
    <div className="w-full h-full bg-[#030303] rounded-sm overflow-hidden border border-gray-900 shadow-inner relative">
      <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />
    </div>
  );
};

export default Visualizer;

import React, { useState, useRef, useCallback, useEffect } from 'react';
import { PlayerState, RadioStation, StereoAnalysers, VisualizerType } from './types';
import { STATIONS } from './constants';
import AudioEngine, { AudioEngineHandle } from './components/AudioEngine';
import Visualizer from './components/Visualizer';

const App: React.FC = () => {
  const [currentStation, setCurrentStation] = useState<RadioStation>(STATIONS[0]);
  const [selectedUrl, setSelectedUrl] = useState<string>(STATIONS[0].url);
  const [playerState, setPlayerState] = useState<PlayerState>(PlayerState.IDLE);
  const [volume, setVolume] = useState(0.8);
  const [isDragging, setIsDragging] = useState(false);
  const [analysers, setAnalysers] = useState<StereoAnalysers | null>(null);
  const [visType, setVisType] = useState<VisualizerType>(VisualizerType.LED_BAR);

  const audioEngineRef = useRef<AudioEngineHandle>(null);

  const handleStationClick = (station: RadioStation) => {
    setCurrentStation(station);
    const defaultUrl = station.qualities && station.qualities.length > 0 
      ? station.qualities[0].url 
      : station.url;

    setSelectedUrl(defaultUrl);
    setTimeout(() => {
      audioEngineRef.current?.play();
    }, 50);
  };

  const handleQualityChange = (url: string) => {
    if (url === selectedUrl) return;
    setSelectedUrl(url);
    setTimeout(() => {
      audioEngineRef.current?.play();
    }, 50);
  };

  const cycleVisualizer = () => {
    const types = Object.values(VisualizerType);
    const currentIndex = types.indexOf(visType);
    const nextIndex = (currentIndex + 1) % types.length;
    setVisType(types[nextIndex]);
  };

  const handleTogglePlay = useCallback(() => {
    audioEngineRef.current?.toggle();
  }, []);

  const isPlaying = playerState === PlayerState.PLAYING;
  const isLoading = playerState === PlayerState.LOADING;

  const currentQuality = currentStation.qualities?.find(q => q.url === selectedUrl);
  const currentBitrate = currentQuality?.bitrate || currentStation.bitrate || '128kbps';

  return (
    <div className="flex flex-col h-[100dvh] w-full bg-[#111] overflow-hidden select-none">
      <div className="safe-top bg-black"></div>

      <div className="p-2 space-y-2 max-w-md mx-auto w-full flex-1 flex flex-col overflow-hidden">
        {/* MASTER RACK WINDOW */}
        <div className="winamp-window flex flex-col shrink-0">
          <div className="winamp-title-bar flex justify-between">
             <div className="flex items-center gap-1">
                <div className="w-2 h-2 bg-yellow-400 rotate-45"></div>
                <span className="truncate tracking-widest uppercase">REVOXMIX v3.6 - MASTER RACK</span>
             </div>
             <div className="flex gap-2">
                <span className="text-[8px] text-gray-400 font-bold uppercase tracking-widest">Digital Ready</span>
                <div className="w-2.5 h-2.5 bg-[#ccc] border border-black/20"></div>
             </div>
          </div>

          <div className="p-3 space-y-3">
            {/* OPTIMIZED LCD PANEL */}
            <div className="winamp-lcd p-2 flex flex-col relative h-56 overflow-hidden bg-black border-2 border-gray-800 rounded-sm">
               {/* TOP INFO BAR */}
               <div className="flex justify-between items-center border-b border-gray-900 pb-2 mb-2">
                  <div className="flex items-center gap-2 overflow-hidden">
                    <div className={`px-1.5 py-0.5 text-[10px] font-bold rounded-sm transition-colors ${isPlaying ? 'bg-[#00ff00] text-black animate-pulse' : 'bg-gray-800 text-gray-500'}`}>
                      {isPlaying ? 'ON AIR' : 'SIGNAL LOSS'}
                    </div>
                    <span className="text-xl font-bold tracking-tighter text-[#00ff00] truncate font-mono uppercase leading-none">
                      {currentStation.name}
                    </span>
                  </div>
                  <div className="flex flex-col items-end shrink-0 leading-tight">
                    <span className="text-[7px] text-gray-500 font-bold uppercase tracking-widest">Rate</span>
                    <span className="text-xs font-bold text-[#ffff00] tracking-wider font-mono">
                      {currentBitrate.toUpperCase()}
                    </span>
                  </div>
               </div>

               {/* MAIN DISPLAY AREA */}
               <div className="flex flex-col flex-1 min-h-0">
                  <div className="flex justify-between items-center mb-2 px-1">
                    <div className="flex flex-col gap-1.5">
                       <span className="text-[10px] text-[#00ff00] font-bold uppercase tracking-[0.1em] font-mono leading-none">
                         {selectedUrl.includes('m3u8') ? 'HLS-LINK' : 'MP3-STREAM'}
                       </span>
                       <button 
                        onClick={cycleVisualizer}
                        className="text-[9px] border border-gray-700 px-2 py-1 hover:bg-gray-900 transition-colors uppercase font-mono text-[#00ff00] bg-[#1a1a1a] border-b-2 active:translate-y-[1px]"
                       >
                         VIS: {visType.replace('_', ' ')}
                       </button>
                    </div>

                    {currentStation.qualities && currentStation.qualities.length > 1 && (
                      <div className="flex flex-col items-end gap-1 max-w-[50%]">
                        <span className="text-[7px] text-gray-500 font-bold uppercase">CHANNEL SELECT</span>
                        <select 
                          value={selectedUrl}
                          onChange={(e) => handleQualityChange(e.target.value)}
                          className="bg-[#111] border border-gray-800 text-[#00ff00] text-[10px] font-mono outline-none py-1 px-2 w-full uppercase"
                        >
                          {currentStation.qualities.map((q) => (
                            <option key={q.url} value={q.url}>
                              {q.label}
                            </option>
                          ))}
                        </select>
                      </div>
                    )}
                  </div>

                  {/* VISUALIZER CONTAINER */}
                  <div className="flex-1 relative mb-1 mt-1">
                    <Visualizer analysers={analysers} isPaused={!isPlaying} type={visType} />
                  </div>
               </div>

               {/* LOADING OVERLAY */}
               {isLoading && (
                 <div className="absolute inset-0 bg-black/90 flex flex-col items-center justify-center z-20">
                    <div className="w-8 h-8 border-4 border-t-[#00ff00] border-gray-800 rounded-full animate-spin mb-2"></div>
                    <span className="text-[11px] font-mono tracking-[0.3em] text-[#00ff00]">BUFFERING...</span>
                 </div>
               )}
