import React, { useEffect, useRef, forwardRef, useImperativeHandle } from 'react';
import { PlayerState, StereoAnalysers } from '../types';

declare const Hls: any;

interface AudioEngineProps {
  url: string;
  volume: number;
  isMuted: boolean;
  onStateChange: (state: PlayerState) => void;
  onAnalyserCreated: (analysers: StereoAnalysers) => void;
}

export interface AudioEngineHandle {
  play: () => void;
  pause: () => void;
  toggle: () => void;
}

const AudioEngine = forwardRef<AudioEngineHandle, AudioEngineProps>(({
  url,
  volume,
  isMuted,
  onStateChange,
  onAnalyserCreated
}, ref) => {
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const hlsRef = useRef<any>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);
  const analyserLRef = useRef<AnalyserNode | null>(null);
  const analyserRRef = useRef<AnalyserNode | null>(null);

  const initAudioContext = async () => {
    if (!audioRef.current) return;

    if (!audioContextRef.current) {
      const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
      const ctx = new AudioContextClass();
      audioContextRef.current = ctx;

      // Creamos la fuente desde el elemento audio
      // NOTA: Para que esto funcione con streams externos, el servidor DEBE permitir CORS.
      sourceRef.current = ctx.createMediaElementSource(audioRef.current);

      const createOptimizedAnalyser = () => {
        const a = ctx.createAnalyser();
        a.fftSize = 512;
        a.smoothingTimeConstant = 0.6; // Más reactivo para streams de radio
        a.minDecibels = -90; 
        a.maxDecibels = -10;
        return a;
      };

      analyserLRef.current = createOptimizedAnalyser();
      analyserRRef.current = createOptimizedAnalyser();

      const splitter = ctx.createChannelSplitter(2);
      const merger = ctx.createChannelMerger(2);
      const gainNode = ctx.createGain(); // Ganancia principal

      // Conexión: Fuente -> Splitter -> Analizadores
      sourceRef.current.connect(splitter);

      // Canal Izquierdo
      splitter.connect(analyserLRef.current, 0);

      // Canal Derecho (con salvaguarda para mono)
      try {
        splitter.connect(analyserRRef.current, 1);
      } catch (e) {
        // Si falla (fuente mono), conectamos el mismo canal 0 al analizador derecho
        splitter.connect(analyserRRef.current, 0);
      }

      // Conectamos a la salida real
      sourceRef.current.connect(ctx.destination);

      onAnalyserCreated({
        left: analyserLRef.current,
        right: analyserRRef.current
      });
    }

    if (audioContextRef.current.state === 'suspended') {
      await audioContextRef.current.resume();
    }
  };

  useImperativeHandle(ref, () => ({
    play: async () => {
      await initAudioContext();
      audioRef.current?.play().catch(e => console.error("Error playing audio:", e));
    },
    pause: () => audioRef.current?.pause(),
    toggle: async () => {
      await initAudioContext();
      if (audioRef.current?.paused) {
        audioRef.current.play().catch(e => console.error("Error playing audio:", e));
      } else {
        audioRef.current?.pause();
      }
    }
  }));

  useEffect(() => {
    if (!audioRef.current) return;
    onStateChange(PlayerState.LOADING);

    if (hlsRef.current) {
      hlsRef.current.destroy();
      hlsRef.current = null;
    }

    audioRef.current.pause();
    // Limpieza agresiva de src para evitar leaks y asegurar reinicio de buffering
    audioRef.current.removeAttribute('src');
    audioRef.current.load();

    const isHls = url.toLowerCase().includes('.m3u8') || url.toLowerCase().includes('master');

    if (isHls && Hls.isSupported()) {
      const hls = new Hls({
        enableWorker: true,
        lowLatencyMode: true,
      });
      hlsRef.current = hls;
      hls.loadSource(url);
      hls.attachMedia(audioRef.current);
      hls.on(Hls.Events.ERROR, (_: any, data: any) => {
        if (data.fatal) onStateChange(PlayerState.ERROR);
      });
    } else {
      audioRef.current.src = url;
    }
  }, [url]);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = volume;
      audioRef.current.muted = isMuted;
    }
  }, [volume, isMuted]);

  return (
    <audio
      ref={audioRef}
      onPlay={() => onStateChange(PlayerState.PLAYING)}
      onPause={() => onStateChange(PlayerState.PAUSED)}
      onWaiting={() => onStateChange(PlayerState.LOADING)}
      onPlaying={() => onStateChange(PlayerState.PLAYING)}
      onError={() => onStateChange(PlayerState.ERROR)}
      crossOrigin="anonymous"
      preload="auto"
    />
  );
});

AudioEngine.displayName = 'AudioEngine';
export default AudioEngine;

import React, { useEffect, useRef } from 'react';
import { StereoAnalysers, VisualizerType } from '../types';

interface VisualizerProps {
  analysers: StereoAnalysers | null;
  isPaused: boolean;
  type: VisualizerType;
}

const Visualizer: React.FC<VisualizerProps> = ({ analysers, isPaused, type }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const peaksRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });
  const lastValuesRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });
  const needleRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });

  useEffect(() => {
    if (!canvasRef.current || !analysers) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    const resizeCanvas = () => {
      const parent = canvas.parentElement;
      if (!parent) return;
      const rect = parent.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.scale(dpr, dpr);
    };

    const resizeObserver = new ResizeObserver(resizeCanvas);
    resizeObserver.observe(canvas.parentElement!);
    resizeCanvas();

    const dataL = new Uint8Array(analysers.left.frequencyBinCount);
    const dataR = new Uint8Array(analysers.right.frequencyBinCount);
    const timeL = new Uint8Array(analysers.left.fftSize);
    const timeR = new Uint8Array(analysers.right.fftSize);

    let animationId: number;

    const draw = () => {
      animationId = requestAnimationFrame(draw);

      analysers.left.getByteFrequencyData(dataL);
      analysers.right.getByteFrequencyData(dataR);
      analysers.left.getByteTimeDomainData(timeL);
      analysers.right.getByteTimeDomainData(timeR);

      const width = canvas.width / dpr;
      const height = canvas.height / dpr;

      // Limpieza con color LCD profundo
      ctx.fillStyle = '#050a05'; 
      ctx.fillRect(0, 0, width, height);

      // Verificamos si hay señal real (CORS check)
      const hasSignal = !isPaused && (dataL.some(v => v > 0) || dataR.some(v => v > 0));

      // Si no hay señal y no estamos pausados, podría ser problema de CORS o buffer
      if (!hasSignal && !isPaused) {
        // Dibujamos un mensaje tenue de "Waiting Signal"
        ctx.fillStyle = 'rgba(0, 255, 0, 0.1)';
        ctx.font = '10px monospace';
        ctx.textAlign = 'center';
        ctx.fillText('CHECKING SIGNAL...', width / 2, height / 2);
      }

      if (type === VisualizerType.LED_BAR) {
        drawLedBars(ctx, dataL, dataR, width, height, isPaused);
      } else if (type === VisualizerType.SPECTRUM) {
        drawSpectrum(ctx, dataL, dataR, width, height, isPaused);
      } else if (type === VisualizerType.ANALOG) {
        drawAnalogVU(ctx, dataL, dataR, width, height, isPaused);
      } else if (type === VisualizerType.OSCILLOSCOPE) {
        drawOscilloscope(ctx, timeL, timeR, width, height, isPaused);
      }

      // Efecto Scanline CRT
      ctx.fillStyle = 'rgba(0, 0, 0, 0.15)';
      for (let i = 0; i < height; i += 3) {
        ctx.fillRect(0, i, width, 1);
      }
    };

    const drawLedBars = (ctx: CanvasRenderingContext2D, dataL: Uint8Array, dataR: Uint8Array, width: number, height: number, paused: boolean) => {
      const getLevel = (data: Uint8Array) => {
        if (paused) return 0;
        let sum = 0;
        const count = 12; // Bajamos el rango para pillar bajos/medios que tienen más energía
        for(let i = 1; i <= count; i++) sum += data[i];
        const avg = sum / count;
        return Math.min(255, avg * 1.5); // Amplificamos visualmente
      };

      const smooth = (curr: number, target: number) => {
        const factor = target > curr ? 0.7 : 0.2;
        return curr + (target - curr) * factor;
      };

      lastValuesRef.current.left = smooth(lastValuesRef.current.left, getLevel(dataL));
      lastValuesRef.current.right = smooth(lastValuesRef.current.right, getLevel(dataR));

      const barHeight = (height / 2) - 4;

      const drawBar = (y: number, value: number, peakKey: 'left' | 'right', label: string) => {
        const xStart = 15;
        const meterWidth = width - 25;

        if (value > peaksRef.current[peakKey]) peaksRef.current[peakKey] = value;
        else peaksRef.current[peakKey] *= 0.96;

        // Fondo del canal
        ctx.fillStyle = '#0a1a0a';
        ctx.fillRect(xStart, y, meterWidth, barHeight);

        // Etiqueta L/R
        ctx.fillStyle = '#00ff00';
        ctx.font = 'bold 8px monospace';
        ctx.fillText(label, 2, y + barHeight / 2 + 3);

        const numSegs = 45;
        const segW = meterWidth / numSegs;
        const activeIdx = (value / 255) * numSegs;
        const peakIdx = (peaksRef.current[peakKey] / 255) * numSegs;

        for (let i = 0; i < numSegs; i++) {
          const sx = xStart + (i * segW);
          if (i <= activeIdx) {
            if (i > numSegs * 0.85) ctx.fillStyle = '#ff3333';
            else if (i > numSegs * 0.7) ctx.fillStyle = '#ffff00';
            else ctx.fillStyle = '#00ff66';
          } else if (Math.floor(peakIdx) === i && i > 0) {
            ctx.fillStyle = '#ffffff';
          } else {
            ctx.fillStyle = '#1a2a1a';
          }
          ctx.fillRect(sx, y + 1, segW - 1, barHeight - 2);
        }
      };

      drawBar(2, lastValuesRef.current.left, 'left', 'L');
      drawBar(height / 2 + 2, lastValuesRef.current.right, 'right', 'R');
    };

    const drawSpectrum = (ctx: CanvasRenderingContext2D, dataL: Uint8Array, dataR: Uint8Array, width: number, height: number, paused: boolean) => {
      const bars = 40;
      const bW = width / bars;
      for (let i = 0; i < bars; i++) {
        const val = paused ? 2 : (dataL[i] + dataR[i]) / 2;
        const h = (val / 255) * height;
        ctx.fillStyle = `hsl(${(i/bars)*120 + 100}, 100%, 50%)`;
        ctx.fillRect(i * bW, height - h, bW - 1, h);
      }
    };

    const drawAnalogVU = (ctx: CanvasRenderingContext2D, dataL: Uint8Array, dataR: Uint8Array, width: number, height: number, paused: boolean) => {
      const getVal = (data: Uint8Array) => {
        if (paused) return 0;
        let s = 0; for(let i=0; i<8; i++) s += data[i];
        return (s/8)/255;
      };

      needleRef.current.left += (getVal(dataL) - needleRef.current.left) * 0.2;
      needleRef.current.right += (getVal(dataR) - needleRef.current.right) * 0.2;

      const drawGauge = (x: number, level: number) => {
        const r = height * 1.2;
        const start = -Math.PI * 0.75;
        const end = -Math.PI * 0.25;
        const angle = start + level * (end - start);

        ctx.strokeStyle = '#223322';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(x, height + 5, r - 10, start, end);
        ctx.stroke();

        ctx.strokeStyle = '#ff3344';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(x, height + 5);
        ctx.lineTo(x + Math.cos(angle) * (r - 5), height + 5 + Math.sin(angle) * (r - 5));
        ctx.stroke();
      };
      drawGauge(width * 0.3, needleRef.current.left);
      drawGauge(width * 0.7, needleRef.current.right);
    };

    const drawOscilloscope = (ctx: CanvasRenderingContext2D, timeL: Uint8Array, timeR: Uint8Array, width: number, height: number, paused: boolean) => {
      ctx.strokeStyle = '#00ff88';
      ctx.lineWidth = 2;
      ctx.beginPath();
      const step = width / timeL.length;
      for (let i = 0; i < timeL.length; i++) {
        const v = paused ? 128 : (timeL[i] + timeR[i]) / 2;
        const y = (v / 255) * height;
        if (i === 0) ctx.moveTo(0, y); else ctx.lineTo(i * step, y);
      }
      ctx.stroke();
    };

    draw();
    return () => {
      cancelAnimationFrame(animationId);
      resizeObserver.disconnect();
    };
  }, [analysers, isPaused, type]);

  return (
    <div className="w-full h-full bg-[#051505] rounded-sm overflow-hidden border border-[#004400] relative">
      <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />
    </div>
  );
};

export default Visualizer;

import React, { useState, useRef, useCallback, useEffect } from 'react';
import { PlayerState, RadioStation, StereoAnalysers, VisualizerType } from './types';
