          <div className="winamp-title-bar flex justify-between">
             <div className="flex items-center gap-1">
                <div className="w-2 h-2 bg-yellow-400 rotate-45"></div>
                <span className="truncate tracking-widest uppercase">REVOXMIX v3.8 - MASTER RACK</span>
             </div>
             <div className="flex gap-2">
                <span className="text-[8px] text-gray-400 font-bold uppercase tracking-widest">Hi-Fi Digital</span>
                <div className="w-2.5 h-2.5 bg-[#ccc] border border-black/20"></div>
             </div>
          </div>

          <div className="p-3 space-y-2">
            {/* OPTIMIZED LCD PANEL */}
