}

const Visualizer: React.FC<VisualizerProps> = ({ analysers, isPaused }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const peaksRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });
  const lastValuesRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });

  useEffect(() => {
    if (!canvasRef.current || !analysers) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    const resizeCanvas = () => {
      const parent = canvas.parentElement;
      if (!parent) return;
      const rect = parent.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.scale(dpr, dpr);
    };

    const resizeObserver = new ResizeObserver(resizeCanvas);
    resizeObserver.observe(canvas.parentElement!);
    resizeCanvas();

    const dataL = new Uint8Array(analysers.left.frequencyBinCount);
    const dataR = new Uint8Array(analysers.right.frequencyBinCount);

    let animationId: number;

    const draw = () => {
      animationId = requestAnimationFrame(draw);

      analysers.left.getByteFrequencyData(dataL);
      analysers.right.getByteFrequencyData(dataR);

      const width = canvas.width / dpr;
      const height = canvas.height / dpr;

      // LCD Background
      ctx.fillStyle = '#050a05'; 
      ctx.fillRect(0, 0, width, height);

      const getLevel = (data: Uint8Array) => {
        if (isPaused) return 0;
        let sum = 0;
        const count = 16; 
        for(let i = 1; i <= count; i++) sum += data[i];
        const avg = sum / count;
        return Math.min(255, avg * 1.6);
      };

      const smooth = (curr: number, target: number) => {
        const factor = target > curr ? 0.75 : 0.15;
        return curr + (target - curr) * factor;
      };

      lastValuesRef.current.left = smooth(lastValuesRef.current.left, getLevel(dataL));
      lastValuesRef.current.right = smooth(lastValuesRef.current.right, getLevel(dataR));

      const barHeight = (height / 2) - 4;

      const drawBar = (y: number, value: number, peakKey: 'left' | 'right', label: string) => {
        const xStart = 12;
        const meterWidth = width - 20;

        if (value > peaksRef.current[peakKey]) peaksRef.current[peakKey] = value;
        else peaksRef.current[peakKey] *= 0.97;

        // Background groove
        ctx.fillStyle = '#102010';
        ctx.fillRect(xStart, y, meterWidth, barHeight);

        // Channel Label
        ctx.fillStyle = '#00ff00';
        ctx.font = 'bold 8px monospace';
        ctx.fillText(label, 2, y + barHeight / 2 + 3);

        const numSegs = 40;
        const segW = meterWidth / numSegs;
        const activeIdx = (value / 255) * numSegs;
        const peakIdx = (peaksRef.current[peakKey] / 255) * numSegs;

        for (let i = 0; i < numSegs; i++) {
          const sx = xStart + (i * segW);
          if (i <= activeIdx) {
            if (i > numSegs * 0.85) ctx.fillStyle = '#ff3333';
            else if (i > numSegs * 0.65) ctx.fillStyle = '#ffff00';
            else ctx.fillStyle = '#00ff66';
          } else if (Math.floor(peakIdx) === i && i > 0) {
            ctx.fillStyle = '#ffffff';
          } else {
            ctx.fillStyle = '#152515';
          }
          ctx.fillRect(sx, y + 1, segW - 1.2, barHeight - 2);
        }
      };

      drawBar(2, lastValuesRef.current.left, 'left', 'L');
      drawBar(height / 2 + 2, lastValuesRef.current.right, 'right', 'R');

      // CRT Scanlines
      ctx.fillStyle = 'rgba(0, 0, 0, 0.1)';
      for (let i = 0; i < height; i += 2) ctx.fillRect(0, i, width, 1);
    };

    draw();
    return () => {
      cancelAnimationFrame(animationId);
      resizeObserver.disconnect();
    };
  }, [analysers, isPaused]);

  return (
    <div className="w-full h-full bg-[#051505] rounded-sm overflow-hidden relative">
      <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />
    </div>
  );
};

export default Visualizer;

