import React, { useEffect, useRef } from 'react';
import { StereoAnalysers } from '../types';

interface VisualizerProps {
  analysers: StereoAnalysers | null;
  isPaused: boolean;
}

const Visualizer: React.FC<VisualizerProps> = ({ analysers, isPaused }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const peaksRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });
  const lastLevelsRef = useRef<{ left: number; right: number }>({ left: 0, right: 0 });

  useEffect(() => {
    if (!canvasRef.current || !analysers) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    const resizeCanvas = () => {
      const parent = canvas.parentElement;
      if (!parent) return;
      const rect = parent.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.scale(dpr, dpr);
    };

    const resizeObserver = new ResizeObserver(resizeCanvas);
    resizeObserver.observe(canvas.parentElement!);
    resizeCanvas();

    const bufferL = new Uint8Array(analysers.left.fftSize);
    const bufferR = new Uint8Array(analysers.right.fftSize);

    let animationId: number;

    const draw = () => {
      animationId = requestAnimationFrame(draw);

      // Usamos Time Domain para obtener el nivel real (RMS)
      analysers.left.getByteTimeDomainData(bufferL);
      analysers.right.getByteTimeDomainData(bufferR);

      const width = canvas.width / dpr;
      const height = canvas.height / dpr;

      // Fondo LCD
      ctx.fillStyle = '#050a05'; 
      ctx.fillRect(0, 0, width, height);

      // Cálculo de nivel RMS (Root Mean Square) para movimiento real
      const calculateRMS = (data: Uint8Array) => {
        if (isPaused) return 0;
        let sum = 0;
        for (let i = 0; i < data.length; i++) {
          const val = (data[i] - 128) / 128;
          sum += val * val;
        }
        const rms = Math.sqrt(sum / data.length);
        // Escalado para visualización (el factor 4.5 aumenta la sensibilidad)
        return Math.min(1, rms * 4.5);
      };

      const targetL = calculateRMS(bufferL);
      const targetR = calculateRMS(bufferR);

      // Balística del vúmetro (Ataque rápido, caída lenta)
      const smooth = (curr: number, target: number) => {
        const attack = 0.4;
        const release = 0.1;
        const factor = target > curr ? attack : release;
        return curr + (target - curr) * factor;
      };

      lastLevelsRef.current.left = smooth(lastLevelsRef.current.left, targetL);
      lastLevelsRef.current.right = smooth(lastLevelsRef.current.right, targetR);

      const barHeight = (height / 2) - 3;

      const drawBar = (y: number, level: number, peakKey: 'left' | 'right', label: string) => {
        const xStart = 15;
        const meterWidth = width - 25;

        // Manejo de picos
        if (level > peaksRef.current[peakKey]) {
          peaksRef.current[peakKey] = level;
        } else {
          peaksRef.current[peakKey] *= 0.98;
        }

        // Canal Label
        ctx.fillStyle = '#00ff00';
        ctx.font = 'bold 9px monospace';
        ctx.textAlign = 'left';
        ctx.fillText(label, 3, y + barHeight / 2 + 3);

        // Fondo del medidor
        ctx.fillStyle = '#101a10';
        ctx.fillRect(xStart, y, meterWidth, barHeight);

        const numSegs = 35;
        const segW = meterWidth / numSegs;
        const activeIdx = level * numSegs;
        const peakIdx = peaksRef.current[peakKey] * numSegs;

        for (let i = 0; i < numSegs; i++) {
          const sx = xStart + (i * segW);
          const isPeak = Math.floor(peakIdx) === i && i > 0;

          if (i <= activeIdx) {
            // Colores clásicos de vúmetro
            if (i > numSegs * 0.85) ctx.fillStyle = '#ff0000'; // Rojo (Clip)
            else if (i > numSegs * 0.7) ctx.fillStyle = '#ffff00'; // Amarillo (Warning)
            else ctx.fillStyle = '#00ff00'; // Verde (Normal)
          } else if (isPeak) {
            ctx.fillStyle = '#ffffff';
          } else {
            ctx.fillStyle = '#152015';
          }

          ctx.fillRect(sx, y + 1, segW - 1.5, barHeight - 2);
        }
      };

      drawBar(1, lastLevelsRef.current.left, 'left', 'L');
      drawBar(height / 2 + 1, lastLevelsRef.current.right, 'right', 'R');

      // Líneas de escala (Decibelios aproximados)
      ctx.fillStyle = 'rgba(0, 255, 0, 0.2)';
      ctx.font = '6px Arial';
      const scaleX = [0.5, 0.7, 0.85, 1];
      const scaleLabels = ['-10', '-5', '0', '+3'];
      scaleX.forEach((p, i) => {
        const x = 15 + p * (width - 25);
        ctx.fillRect(x, 0, 1, height);
      });

      // Efecto scanline CRT
      ctx.fillStyle = 'rgba(0, 0, 0, 0.15)';
      for (let i = 0; i < height; i += 3) ctx.fillRect(0, i, width, 1);
    };

    draw();
    return () => {
      cancelAnimationFrame(animationId);
      resizeObserver.disconnect();
    };
  }, [analysers, isPaused]);

  return (
    <div className="w-full h-full bg-[#030803] rounded-sm overflow-hidden relative shadow-inner">
      <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />
    </div>
  );
};

export default Visualizer;

import React, { useEffect, useRef, forwardRef, useImperativeHandle } from 'react';
import { PlayerState, StereoAnalysers } from '../types';

declare const Hls: any;

interface AudioEngineProps {
  url: string;
  volume: number;
  isMuted: boolean;
  onStateChange: (state: PlayerState) => void;
  onAnalyserCreated: (analysers: StereoAnalysers) => void;
}

export interface AudioEngineHandle {
  play: () => void;
  pause: () => void;
  toggle: () => void;
}

const AudioEngine = forwardRef<AudioEngineHandle, AudioEngineProps>(({
  url,
  volume,
  isMuted,
  onStateChange,
  onAnalyserCreated
}, ref) => {
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const hlsRef = useRef<any>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);
  const analyserLRef = useRef<AnalyserNode | null>(null);
  const analyserRRef = useRef<AnalyserNode | null>(null);

  const initAudioContext = async () => {
    if (!audioRef.current) return;

    if (!audioContextRef.current) {
      const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
      const ctx = new AudioContextClass();
      audioContextRef.current = ctx;

      // Crear analizadores con mayor resolución
      const createAnalyser = () => {
        const a = ctx.createAnalyser();
        a.fftSize = 1024; // Aumentamos tamaño para mayor precisión de dominio de tiempo
        a.smoothingTimeConstant = 0.5;
        return a;
      };

      analyserLRef.current = createAnalyser();
      analyserRRef.current = createAnalyser();

      const splitter = ctx.createChannelSplitter(2);

      // Fuente desde el elemento de audio
      sourceRef.current = ctx.createMediaElementSource(audioRef.current);

      // Cadena de conexión: Audio -> Splitter -> Analizadores L/R
      sourceRef.current.connect(splitter);
      splitter.connect(analyserLRef.current, 0);

      try {
        splitter.connect(analyserRRef.current, 1);
      } catch (e) {
        // Fallback para streams mono: enviar el mismo canal a ambos
        splitter.connect(analyserRRef.current, 0);
      }

      // Conexión a la salida final del sistema
      sourceRef.current.connect(ctx.destination);

      onAnalyserCreated({
        left: analyserLRef.current,
        right: analyserRRef.current
      });
    }

    if (audioContextRef.current.state === 'suspended') {
      await audioContextRef.current.resume();
    }
  };

  useImperativeHandle(ref, () => ({
    play: async () => {
      await initAudioContext();
      audioRef.current?.play().catch(e => console.warn("Interacción requerida para audio:", e));
    },
    pause: () => audioRef.current?.pause(),
    toggle: async () => {
      await initAudioContext();
      if (audioRef.current?.paused) {
        audioRef.current.play().catch(e => console.warn("Interacción requerida para audio:", e));
      } else {
        audioRef.current?.pause();
      }
    }
  }));

  useEffect(() => {
    if (!audioRef.current) return;
    onStateChange(PlayerState.LOADING);

    if (hlsRef.current) {
      hlsRef.current.destroy();
      hlsRef.current = null;
    }

    audioRef.current.pause();
    audioRef.current.removeAttribute('src');
    audioRef.current.load();

    // Detección de HLS
    const isHls = url.toLowerCase().includes('.m3u8') || url.toLowerCase().includes('master');

    if (isHls && Hls.isSupported()) {
      const hls = new Hls({
        enableWorker: true,
        lowLatencyMode: true,
        xhrSetup: (xhr: any) => {
          xhr.withCredentials = false; // CORS setup
        }
      });
      hlsRef.current = hls;
      hls.loadSource(url);
      hls.attachMedia(audioRef.current);
      hls.on(Hls.Events.ERROR, (_: any, data: any) => {
        if (data.fatal) onStateChange(PlayerState.ERROR);
      });
    } else {
      audioRef.current.src = url;
    }
  }, [url]);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = volume;
      audioRef.current.muted = isMuted;
    }
  }, [volume, isMuted]);

  return (
    <audio
      ref={audioRef}
      onPlay={() => onStateChange(PlayerState.PLAYING)}
      onPause={() => onStateChange(PlayerState.PAUSED)}
      onWaiting={() => onStateChange(PlayerState.LOADING)}
      onPlaying={() => onStateChange(PlayerState.PLAYING)}
      onError={() => onStateChange(PlayerState.ERROR)}
      crossOrigin="anonymous"
      preload="auto"
    />
  );
});

