import React, { useState, useRef, useCallback, useEffect } from 'react';
import { PlayerState, RadioStation } from './types';
import { STATIONS } from './constants';
import AudioEngine, { AudioEngineHandle } from './components/AudioEngine';

const DigitalVUMeter: React.FC<{ analyser: AnalyserNode | null; isPlaying: boolean }> = ({ analyser, isPlaying }) => {
  const [levels, setLevels] = useState({ left: 0, right: 0 });
  const animationRef = useRef<number>(0);

  useEffect(() => {
    if (!analyser || !isPlaying) {
      setLevels({ left: 0, right: 0 });
      return;
    }

    const dataArray = new Uint8Array(analyser.frequencyBinCount);
    const update = () => {
      analyser.getByteFrequencyData(dataArray);

      // Calculate a pseudo-stereo effect from frequency bands
      let leftSum = 0;
      let rightSum = 0;
      const half = Math.floor(dataArray.length / 2);

      for (let i = 0; i < half; i++) leftSum += dataArray[i];
      for (let i = half; i < dataArray.length; i++) rightSum += dataArray[i];

      const leftLevel = (leftSum / half) / 255;
      const rightLevel = (rightSum / half) / 255;

      setLevels({ 
        left: Math.min(1, leftLevel * 1.5), 
        right: Math.min(1, rightLevel * 1.5) 
      });
      animationRef.current = requestAnimationFrame(update);
    };

    update();
    return () => cancelAnimationFrame(animationRef.current);
  }, [analyser, isPlaying]);

  const renderBar = (level: number) => {
    const segments = 24;
    return (
      <div className="flex gap-[1px] h-2 w-full bg-gray-950 p-[1px] border border-gray-900">
        {Array.from({ length: segments }).map((_, i) => {
          const isActive = (i / segments) < level;
          let colorClass = "bg-gray-900";
          if (isActive) {
            if (i > segments * 0.85) colorClass = "bg-red-500 shadow-[0_0_5px_#ef4444]";
