          }
          return <div key={i} className={`flex-1 h-full transition-colors duration-75 ${colorClass}`} />;
        })}
      </div>
    );
  };

  return (
    <div className="flex flex-col gap-1 w-full opacity-80">
      <div className="flex items-center gap-2">
