const DigitalVUMeter: React.FC<{ analyser: AnalyserNode | null; isPlaying: boolean }> = ({ analyser, isPlaying }) => {
  const [levels, setLevels] = useState({ left: 0, right: 0 });
  const animationRef = useRef<number>(0);

  useEffect(() => {
    if (!analyser || !isPlaying) {
      setLevels({ left: 0, right: 0 });
      return;
    }

    const dataArray = new Uint8Array(analyser.frequencyBinCount);
    const update = () => {
      analyser.getByteFrequencyData(dataArray);

      let leftSum = 0;
      let rightSum = 0;
      const half = Math.floor(dataArray.length / 2);

      for (let i = 0; i < half; i++) leftSum += dataArray[i];
      for (let i = half; i < dataArray.length; i++) rightSum += dataArray[i];

      const leftLevel = (leftSum / half) / 255;
      const rightLevel = (rightSum / half) / 255;

      setLevels({ 
        left: Math.min(1, leftLevel * 1.6), 
        right: Math.min(1, rightLevel * 1.6) 
      });
      animationRef.current = requestAnimationFrame(update);
    };

    update();
    return () => cancelAnimationFrame(animationRef.current);
  }, [analyser, isPlaying]);

  const renderBar = (level: number) => {
    const segments = 28; // Increased segments for more precision
    return (
      <div className="flex gap-[1px] h-3 w-full bg-gray-950 p-[1.5px] border border-gray-900 rounded-sm">
        {Array.from({ length: segments }).map((_, i) => {
          const isActive = (i / segments) < level;
          let colorClass = "bg-gray-900";
          if (isActive) {
            if (i > segments * 0.85) colorClass = "bg-red-500 shadow-[0_0_8px_#ef4444]";
            else if (i > segments * 0.6) colorClass = "bg-yellow-400 shadow-[0_0_8px_#facc15]";
            else colorClass = "bg-emerald-500 shadow-[0_0_8px_#10b981]";
          }
          return <div key={i} className={`flex-1 h-full transition-colors duration-75 ${colorClass}`} />;
        })}
      </div>
    );
  };

  return (
    <div className="flex flex-col gap-1.5 w-full">
      <div className="flex items-center gap-2">
        <span className="text-[8px] font-mono text-gray-500 font-bold w-4">L CH</span>
        {renderBar(levels.left)}
      </div>
      <div className="flex items-center gap-2">
        <span className="text-[8px] font-mono text-gray-500 font-bold w-4">R CH</span>
        {renderBar(levels.right)}
      </div>
    </div>
  );
};

