const DigitalVUMeter: React.FC<{ analysers: StereoAnalysers | null; isPlaying: boolean }> = ({ analysers, isPlaying }) => {
  const [levels, setLevels] = useState({ left: 0, right: 0 });
  const animationRef = useRef<number>(0);
  const lastLevels = useRef({ left: 0, right: 0 });

  useEffect(() => {
    if (!analysers || !isPlaying) {
      setLevels({ left: 0, right: 0 });
      lastLevels.current = { left: 0, right: 0 };
      return;
    }

    const dataArrayL = new Uint8Array(analysers.left.frequencyBinCount);
    const dataArrayR = new Uint8Array(analysers.right.frequencyBinCount);

    const update = () => {
      analysers.left.getByteFrequencyData(dataArrayL);
      analysers.right.getByteFrequencyData(dataArrayR);

      // Calculate average power for each channel
      let leftSum = 0;
      let rightSum = 0;

      // We look at the first 60% of bins where most energy is
      const count = Math.floor(dataArrayL.length * 0.6);
      for (let i = 0; i < count; i++) {
        leftSum += dataArrayL[i];
        rightSum += dataArrayR[i];
      }

      let targetL = (leftSum / count) / 255;
      let targetR = (rightSum / count) / 255;

      // Multiplier for visual impact
      targetL = Math.min(1, targetL * 2.5);
      targetR = Math.min(1, targetR * 2.5);

      // Smooth peak decay logic (Vu meter ballistics)
      const decay = 0.15;
      const attack = 0.4;

      const newL = targetL > lastLevels.current.left 
        ? lastLevels.current.left + (targetL - lastLevels.current.left) * attack
        : lastLevels.current.left - decay;

      const newR = targetR > lastLevels.current.right
        ? lastLevels.current.right + (targetR - lastLevels.current.right) * attack
        : lastLevels.current.right - decay;

      const finalL = Math.max(0, newL);
      const finalR = Math.max(0, newR);

      lastLevels.current = { left: finalL, right: finalR };
      setLevels({ left: finalL, right: finalR });

      animationRef.current = requestAnimationFrame(update);
    };

    update();
    return () => {
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
    };
  }, [analysers, isPlaying]);

  const renderBar = (level: number) => {
    const segments = 32;
    return (
      <div className="flex gap-[1px] h-2.5 w-full bg-gray-950 p-[1px] border border-gray-900 rounded-sm overflow-hidden">
        {Array.from({ length: segments }).map((_, i) => {
          const isActive = (i / segments) < level;
          let colorClass = "bg-gray-900";
          if (isActive) {
            if (i > segments * 0.85) colorClass = "bg-red-500 shadow-[0_0_8px_#ef4444]";
            else if (i > segments * 0.6) colorClass = "bg-yellow-400 shadow-[0_0_8px_#facc15]";
            else colorClass = "bg-emerald-500 shadow-[0_0_8px_#10b981]";
          }
          return <div key={i} className={`flex-1 h-full transition-colors duration-75 ${colorClass}`} />;
        })}
      </div>
    );
  };

  return (
    <div className="flex flex-col gap-1 w-full">
      <div className="flex items-center gap-1.5">
        <span className="text-[7px] font-mono text-gray-600 font-bold w-3">L</span>
        {renderBar(levels.left)}
      </div>
      <div className="flex items-center gap-1.5">
        <span className="text-[7px] font-mono text-gray-600 font-bold w-3">R</span>
        {renderBar(levels.right)}
      </div>
    </div>
  );
};

